    export function bossPatternFire(patternId: number, hard: boolean, hardCue: boolean) {
        let now = game.runtime()
        if (hard) {
            if (hardCue) hardPatternWarning()
            let sustained =
                patternId == 0 || patternId == 2 || patternId == 5 ||
                patternId == 9 || patternId == 10 || patternId == 11 ||
                patternId == 13 || patternId == 14 || patternId == 15 ||
                patternId == 16 || patternId == 18 || patternId == 19 ||
                patternId == 20 || patternId == 21 || patternId == 22 ||
                patternId == 23 || patternId == 24 || patternId == 26 ||
                patternId == 28 || patternId == 31
            let minGap = sustained ? 120 : 80
            if (now - lastBossPatternSoundAt < minGap) return
            lastBossPatternSoundAt = now
            let hardStart = 300 + (patternId % 4) * 24
            if (sustained) {
                SoundRuntime.play(
                    WaveShape.Noise,
                    hardStart,
                    90 + (patternId % 3) * 12,
                    SoundRuntime.bossDistanceVolume(74),
                    72
                )
            } else {
                SoundRuntime.play(
                    WaveShape.Noise,
                    hardStart,
                    58 + (patternId % 3) * 14,
                    SoundRuntime.bossDistanceVolume(124),
                    230
                )
            }
            return
        }
        let subtle =
            patternId == 0 || patternId == 2 || patternId == 9 ||
            patternId == 10 || patternId == 18 || patternId == 26
        let minGap = subtle ? 125 : 85
        if (now - lastBossPatternSoundAt < minGap) return
        lastBossPatternSoundAt = now
        let variant = patternId % 4
        if (subtle) {
            SoundRuntime.play(
                WaveShape.Triangle,
                210 + variant * 24,
                170 + variant * 18,
                SoundRuntime.bossDistanceVolume(34),
                30 + variant * 4
            )
            return
        }
        let heavyBurst =
            patternId == 1 || patternId == 3 || patternId == 4 ||
            patternId == 6 || patternId == 7 || patternId == 8 ||
            patternId == 11 || patternId == 17 || patternId == 19 ||
            patternId == 25 || patternId == 27 || patternId == 29 || patternId == 30 || patternId == 32
        if (heavyBurst) {
            SoundRuntime.play(
                variant % 2 == 0 ? WaveShape.Noise : WaveShape.Sawtooth,
                220 + variant * 16,
                52 + variant * 10,
                SoundRuntime.bossDistanceVolume(116 + variant * 4),
                245 + variant * 18
            )
            return
        }
        let widePattern =
            patternId == 5 || patternId == 12 || patternId == 13 ||
            patternId == 20 || patternId == 21 || patternId == 22 ||
            patternId == 23 || patternId == 24
        if (widePattern) {
            SoundRuntime.play(
                WaveShape.Sawtooth,
                250 + variant * 20,
                105 + variant * 14,
                SoundRuntime.bossDistanceVolume(76 + variant * 4),
                145 + variant * 15
            )
            return
        }
        if (patternId == 14 || patternId == 15 || patternId == 16 || patternId == 28 || patternId == 31) {
            SoundRuntime.play(
                WaveShape.Sawtooth,
                260 + variant * 32,
                170 + variant * 20,
                SoundRuntime.bossDistanceVolume(62),
                95
            )
            return
        }
        SoundRuntime.play(
            variant == 0 ? WaveShape.Triangle : WaveShape.Sawtooth,
            280 + variant * 26,
            150 + variant * 18,
            SoundRuntime.bossDistanceVolume(64 + variant * 5),
            105 + variant * 10
        )
    }
