namespace BossHealthBarVisual {
    const WIDTH = 17
    let cache: Image[] = []
    function imageForFill(fill: number): Image {
        if (fill < 0) fill = 0
        if (fill > WIDTH) fill = WIDTH
        if (cache[fill] != null) return cache[fill]
        let img = image.create(WIDTH, 1)
        img.fillRect(0, 0, WIDTH, 1, 13)
        if (fill > 0) img.fillRect(0, 0, fill, 1, 2)
        cache[fill] = img
        return img
    }
    export function create(owner: Sprite): Sprite {
        let bar = sprites.create(imageForFill(WIDTH), SpriteKind.BossHealth)
        bar.setFlag(SpriteFlag.Ghost, true)
        bar.setFlag(SpriteFlag.AutoDestroy, false)
        bar.setFlag(SpriteFlag.Invisible, true)
        bar.z = owner.z + 2
        return bar
    }
    export function update(
        bar: Sprite,
        owner: Sprite,
        hp: number,
        maxHP: number,
        visible: boolean,
        screenLocked: boolean = false,
        wallSide: number = -1
    ) {
        if (bar == null) return
        if (!visible || owner == null || hp <= 0 || maxHP <= 0) {
            bar.setFlag(SpriteFlag.Invisible, true)
            return
        }
        let fill = Math.idiv(hp * WIDTH, maxHP)
        if (fill < 1) fill = 1
        if (fill > WIDTH) fill = WIDTH
        bar.setImage(imageForFill(fill))
        if (screenLocked) {
            bar.setFlag(SpriteFlag.RelativeToCamera, true)
            let sx = owner.x - WorldSystem.getCameraX() + GameConfig.SCREEN_WIDTH / 2
            let sy = owner.bottom - WorldSystem.getCameraY() + GameConfig.SCREEN_HEIGHT / 2 + 3
            if (wallSide == 3) sy = owner.top - WorldSystem.getCameraY() + GameConfig.SCREEN_HEIGHT / 2 - 3
            let half = Math.idiv(WIDTH + 1, 2)
            if (sx < half + 1) sx = half + 1
            if (sx > GameConfig.SCREEN_WIDTH - half - 1) sx = GameConfig.SCREEN_WIDTH - half - 1
            if (sy < 2) sy = 2
            if (sy > GameConfig.SCREEN_HEIGHT - 2) sy = GameConfig.SCREEN_HEIGHT - 2
            bar.setPosition(sx, sy)
        } else {
            bar.setFlag(SpriteFlag.RelativeToCamera, false)
            bar.setPosition(owner.x, owner.bottom + 3)
        }
        bar.setFlag(SpriteFlag.Invisible, false)
    }
    export function destroy(bar: Sprite) {
        if (bar != null) bar.destroy()
    }
}
