    const PLAYER_VISUAL_STEP_DEG = 5
    const PLAYER_VISUAL_FRAME_COUNT = 72
    let playerVisualFrames: Image[] = []
    function normalizePlayerAngle(angle: number): number {
        while (angle < 0) angle += 360
        while (angle >= 360) angle -= 360
        return angle
    }
    function playerBaseDirectionImage(index: number): Image {
        while (index < 0) index += 8
        while (index >= 8) index -= 8
        if (index == 0) return playerDir0Image()
        if (index == 1) return playerDir45Image()
        if (index == 2) return playerDir90Image()
        if (index == 3) return playerDir135Image()
        if (index == 4) return playerDir180Image()
        if (index == 5) return playerDir225Image()
        if (index == 6) return playerDir270Image()
        return playerDir315Image()
    }
    function rotatePlayerPixels(source: Image, deltaDeg: number): Image {
        let size = 13, c = 6, out = image.create(size, size)
        let r = deltaDeg * Math.PI / 180, cs = Math.cos(r), sn = Math.sin(r)
        for (let y = 0; y < size; y++)for (let x = 0; x < size; x++) {
            let dx = x - c, dy = y - c
            let sx = Math.round(c + dx * cs + dy * sn)
            let sy = Math.round(c - dx * sn + dy * cs)
            if (sx < 0 || sy < 0 || sx >= size || sy >= size) continue
            let color = source.getPixel(sx, sy)
            if (color != 0) out.setPixel(x, y, color)
        }
        return out
    }
    export function playerVisualFrame(angleDeg: number, phase: number): Image {
        angleDeg = normalizePlayerAngle(angleDeg)
        let frameIndex = Math.round(angleDeg / PLAYER_VISUAL_STEP_DEG) % PLAYER_VISUAL_FRAME_COUNT
        if (playerVisualFrames[frameIndex] != null) return playerVisualFrames[frameIndex]
        let visualAngle = frameIndex * PLAYER_VISUAL_STEP_DEG
        let baseIndex = Math.round(visualAngle / 45)
        if (baseIndex >= 8) baseIndex = 0
        let baseAngle = baseIndex * 45
        if (baseIndex == 0 && visualAngle > 337.5) baseAngle = 360
        let delta = visualAngle - baseAngle
        let out = rotatePlayerPixels(playerBaseDirectionImage(baseIndex), delta)
        playerVisualFrames[frameIndex] = out
        return out
    }
