    function safeEnemyPixel(out: Image, x: number, y: number, color: number) {
        if (x >= 0 && x < out.width && y >= 0 && y < out.height) out.setPixel(x, y, color)
    }
    function polishMinionImage(source: Image, baseColor: number, type: number, elite: boolean): Image {
        let out = source.clone()
        let original = source.clone()
        for (let y = 0; y < original.height; y++)for (let x = 0; x < original.width; x++) {
            if (original.getPixel(x, y) != baseColor) continue
            let top = y <= 0 || original.getPixel(x, y - 1) == 0
            let left = x <= 0 || original.getPixel(x - 1, y) == 0
            let bottom = y >= original.height - 1 || original.getPixel(x, y + 1) == 0
            let right = x >= original.width - 1 || original.getPixel(x + 1, y) == 0
            if ((bottom || right) && (x + y) % 3 == 0) out.setPixel(x, y, 15)
            else if ((top || left) && (x * 2 + y) % 4 == 0) out.setPixel(x, y, 1)
        }
        let mid = Math.idiv(out.width, 2)
        let cy = Math.idiv(out.height, 2)
        if (type == 0) { safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15) }
        else if (type == 1) { safeEnemyPixel(out, mid - 2, cy, 15); safeEnemyPixel(out, mid + 2, cy, 15) }
        else if (type == 2) { safeEnemyPixel(out, mid, cy - 2, 1); safeEnemyPixel(out, mid, cy + 2, 15) }
        else if (type == 3) { safeEnemyPixel(out, mid - 2, cy - 1, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15) }
        else if (type == 4) { safeEnemyPixel(out, mid, cy, 15); safeEnemyPixel(out, mid - 1, cy, 1) }
        else if (type == 5) { safeEnemyPixel(out, mid - 2, cy - 1, 1); safeEnemyPixel(out, mid + 2, cy + 1, 15) }
        else if (type == 6) { safeEnemyPixel(out, mid - 1, cy - 2, 1); safeEnemyPixel(out, mid + 1, cy + 2, 15) }
        else if (type == 7) { safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy, 15) }
        else if (type == 8) { safeEnemyPixel(out, mid, cy, 15); safeEnemyPixel(out, mid, cy - 1, 5) }
        else if (type == 9) { safeEnemyPixel(out, mid - 2, cy - 1, 1); safeEnemyPixel(out, mid + 2, cy + 1, 15) }
        else if (type == 10) { safeEnemyPixel(out, mid, cy, 2); safeEnemyPixel(out, mid + 1, Math.max(0, cy - 3), 5) }
        else if (type == 11) { safeEnemyPixel(out, mid, cy - 1, 5); safeEnemyPixel(out, mid, cy + 2, 15) }
        else if (type == 12) { safeEnemyPixel(out, mid - 2, cy - 1, 15); safeEnemyPixel(out, mid + 2, cy - 1, 15) }
        else if (type == 13) { safeEnemyPixel(out, mid, cy, 5); safeEnemyPixel(out, mid, cy - 1, 1) }
        else { safeEnemyPixel(out, mid, cy, 1); safeEnemyPixel(out, mid + 1, cy + 1, 15) }
        if (type == 0) { safeEnemyPixel(out, mid, cy + 2, 15); safeEnemyPixel(out, mid - 1, cy - 3, 1) }
        else if (type == 1) { safeEnemyPixel(out, mid - 3, cy, 15); safeEnemyPixel(out, mid + 3, cy, 15); safeEnemyPixel(out, mid, cy - 1, 5) }
        else if (type == 2) { safeEnemyPixel(out, mid - 1, cy + 1, 15); safeEnemyPixel(out, mid + 1, cy + 1, 15); safeEnemyPixel(out, mid, cy - 3, 1) }
        else if (type == 3) { safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15); safeEnemyPixel(out, mid, cy + 3, 15) }
        else if (type == 4) { safeEnemyPixel(out, mid - 2, cy, 8); safeEnemyPixel(out, mid + 2, cy, 8); safeEnemyPixel(out, mid, cy - 1, 1) }
        else if (type == 5) { safeEnemyPixel(out, mid - 3, cy - 1, 1); safeEnemyPixel(out, mid + 3, cy - 1, 1); safeEnemyPixel(out, mid, cy + 2, 15) }
        else if (type == 6) { safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15); safeEnemyPixel(out, mid, cy - 3, 5) }
        else if (type == 7) { safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy, 15); safeEnemyPixel(out, mid, cy - 1, 1) }
        else if (type == 8) { safeEnemyPixel(out, mid - 1, cy - 1, 5); safeEnemyPixel(out, mid + 1, cy + 1, 15); safeEnemyPixel(out, mid, cy, 4) }
        else if (type == 9) { safeEnemyPixel(out, mid - 2, cy - 1, 1); safeEnemyPixel(out, mid + 2, cy + 1, 15); safeEnemyPixel(out, mid, cy + 2, 4) }
        else if (type == 10) { safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15); safeEnemyPixel(out, mid + 1, cy - 2, 4) }
        else if (type == 11) { safeEnemyPixel(out, mid, cy - 2, 1); safeEnemyPixel(out, mid + 1, cy + 2, 15); safeEnemyPixel(out, mid, cy, 5) }
        else if (type == 12) { safeEnemyPixel(out, mid, cy - 2, 1); safeEnemyPixel(out, mid, cy + 2, 15); safeEnemyPixel(out, mid - 1, cy + 1, 13) }
        else if (type == 13) { safeEnemyPixel(out, mid, cy, 5); safeEnemyPixel(out, mid - 2, cy - 2, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15) }
        else { safeEnemyPixel(out, mid, cy, 1); safeEnemyPixel(out, mid + 2, cy + 2, 15); safeEnemyPixel(out, mid - 2, cy - 2, 1) }
        if (elite) {
            safeEnemyPixel(out, 1, 1, 5); safeEnemyPixel(out, out.width - 2, 1, 5)
            safeEnemyPixel(out, 1, out.height - 2, 12); safeEnemyPixel(out, out.width - 2, out.height - 2, 12)
        }
        if (type == 0) { safeEnemyPixel(out, mid - 1, cy - 1, baseColor); safeEnemyPixel(out, mid + 1, cy - 1, baseColor); safeEnemyPixel(out, mid, cy - 2, 1) }
        else if (type == 3) { safeEnemyPixel(out, mid - 1, cy, baseColor); safeEnemyPixel(out, mid + 1, cy, baseColor); safeEnemyPixel(out, mid, cy + 1, 6) }
        else if (type == 9) { safeEnemyPixel(out, mid - 1, cy, baseColor); safeEnemyPixel(out, mid + 1, cy, baseColor); safeEnemyPixel(out, mid, cy, 15) }
        else if (type == 10) { safeEnemyPixel(out, mid, cy, 15); safeEnemyPixel(out, mid + 1, Math.max(0, cy - 3), 5) }
        return out
    }
    let minionImageCache: Image[] = []
    export function minionImage(type: number, elite: boolean): Image {
        let cacheIndex = type * 2 + (elite ? 1 : 0)
        if (minionImageCache[cacheIndex] != null) return minionImageCache[cacheIndex]
        let size = elite ? 15 : 11
        let imgOut = image.create(size, size)
        let c = minionBaseColor(type)
        let accent = elite ? 2 : 1
        let mid = Math.idiv(size, 2)
        let r = elite ? 5 : 4
        if (type == 0) {
            for (let y = mid - r; y <= mid + r - 1; y++) for (let x = mid - r; x <= mid + r; x++) {
                let dx = x - mid, dy = y - mid
                if (dx * dx + dy * dy <= r * r + 2) imgOut.setPixel(x, y, c)
            }
            for (let x = mid - r; x <= mid + r; x += 2) imgOut.setPixel(x, mid + r, c)
            imgOut.setPixel(mid - 1, mid - 1, 1); imgOut.setPixel(mid + 1, mid - 1, 1)
        } else if (type == 1) {
            for (let x = 1; x < size - 1; x++) {
                let d = Math.abs(x - mid)
                let y = mid - Math.idiv(d, 2)
                imgOut.setPixel(x, y, c); imgOut.setPixel(x, y + 1, c)
                if (d >= 2) imgOut.setPixel(x, mid + 1 + Math.idiv(d, 2), c)
            }
            imgOut.setPixel(mid, mid, c); imgOut.setPixel(mid, mid + 1, accent)
        } else if (type == 2) {
            for (let y = mid - r; y <= mid + r; y++) imgOut.setPixel(mid, y, c)
            for (let x = mid - r; x <= mid + r; x++) imgOut.setPixel(x, mid, c)
            imgOut.setPixel(mid - 1, mid - r, c); imgOut.setPixel(mid + 1, mid - r, c)
            imgOut.setPixel(mid - 1, mid + r, c); imgOut.setPixel(mid + 1, mid + r, c)
            imgOut.setPixel(mid, mid - 1, accent)
        } else if (type == 3) {
            for (let y = mid - 2; y <= mid + r; y++) for (let x = mid - r; x <= mid + r; x++) {
                let dx = x - mid, dy = y - (mid + 1)
                if (dx * dx * 2 + dy * dy <= r * r * 2 + 2) imgOut.setPixel(x, y, c)
            }
            imgOut.setPixel(mid - 1, mid, 1); imgOut.setPixel(mid + 1, mid, 1)
            imgOut.setPixel(mid, mid + 1, 6)
        } else if (type == 4) {
            for (let x = mid - r; x <= mid + r; x++) { imgOut.setPixel(x, mid, c); if (Math.abs(x - mid) < r) { imgOut.setPixel(x, mid - 1, c); imgOut.setPixel(x, mid + 1, c) } }
            imgOut.setPixel(mid, mid, 1); imgOut.setPixel(mid, mid + 1, 8)
            imgOut.setPixel(mid, mid - r, 8); imgOut.setPixel(mid, mid + r, 8); imgOut.setPixel(mid - r, mid, 8); imgOut.setPixel(mid + r, mid, 8)
        } else if (type == 5) {
            for (let y = mid - r; y <= mid + r; y++) { imgOut.setPixel(mid, y, c); let w = Math.max(1, r - Math.abs(y - mid)); imgOut.setPixel(mid - w, y, c); imgOut.setPixel(mid + w, y, c) }
            imgOut.setPixel(mid, mid, accent)
        } else if (type == 6) {
            for (let y = mid - r; y <= mid + r; y++) for (let x = mid - r; x <= mid + r; x++) {
                let dx = x - mid, dy = y - mid
                if (dx * dx + dy * dy <= r * r + 2) imgOut.setPixel(x, y, c)
            }
            for (let y = mid - r + 1; y <= mid + r - 1; y++) imgOut.setPixel(mid, y, accent)
            imgOut.setPixel(mid - 1, mid - r - 1, c); imgOut.setPixel(mid + 1, mid - r - 1, c)
            if (mid - r - 2 >= 0) imgOut.setPixel(mid, mid - r - 2, 4)
        } else if (type == 7) {
            for (let y = mid - r; y <= mid; y++) for (let x = mid - r; x <= mid + r; x++) { let dx = x - mid, dy = y - mid; if (dx * dx + dy * dy <= r * r + 2) imgOut.setPixel(x, y, c) }
            for (let x = mid - r + 1; x <= mid + r - 1; x += 2) for (let y = mid + 1; y <= mid + r; y++) imgOut.setPixel(x, y, c)
            imgOut.setPixel(mid, mid - 1, accent)
        } else if (type == 8) {
            for (let y = mid - 2; y <= mid + 2; y++) for (let x = mid - 2; x <= mid + 2; x++) if (Math.abs(x - mid) + Math.abs(y - mid) <= 3) imgOut.setPixel(x, y, c)
            for (let d = 2; d <= r; d++) { imgOut.setPixel(mid - d, mid - d + 1, c); imgOut.setPixel(mid + d, mid - d + 1, c); imgOut.setPixel(mid - d, mid + d - 1, c); imgOut.setPixel(mid + d, mid + d - 1, c) }
            imgOut.setPixel(mid, mid, 5)
            imgOut.setPixel(mid - 1, mid, 4); imgOut.setPixel(mid + 1, mid, 4)
        } else if (type == 9) {
            for (let x = mid - r + 1; x <= mid + r - 1; x++) for (let y = mid - 2; y <= mid + 2; y++) imgOut.setPixel(x, y, c)
            imgOut.setPixel(mid - r, mid - 2, c); imgOut.setPixel(mid - r, mid - 3, c); imgOut.setPixel(mid + r, mid - 2, c); imgOut.setPixel(mid + r, mid - 3, c)
            imgOut.setPixel(mid - 1, mid, 1); imgOut.setPixel(mid + 1, mid, 1)
        } else if (type == 10) {
            for (let y = mid - r; y <= mid + r; y++) for (let x = mid - r; x <= mid + r; x++) { let dx = x - mid, dy = y - mid; if (dx * dx + dy * dy <= r * r) imgOut.setPixel(x, y, c) }
            imgOut.setPixel(mid + r - 1, mid - r, 5); imgOut.setPixel(mid + r, mid - r - 1, 5); imgOut.setPixel(mid, mid, accent)
        } else if (type == 11) {
            for (let y = 1; y < size - 1; y++) { let w = Math.max(0, Math.idiv((size - y), 3)); for (let x = mid - w; x <= mid + w; x++)imgOut.setPixel(x, y, c) }
            imgOut.setPixel(mid, mid, accent)
        } else if (type == 12) {
            for (let y = mid - r; y <= mid + r; y++) for (let x = mid - r; x <= mid + r; x++) if (Math.abs(x - mid) + Math.abs(y - mid) <= r + 2) imgOut.setPixel(x, y, c)
            imgOut.setPixel(mid - 2, mid - 1, 1); imgOut.setPixel(mid + 2, mid - 1, 1); imgOut.setPixel(mid, mid + 2, accent)
        } else if (type == 13) {
            for (let a = 0; a < 8; a++) { let ang = a * Math.PI / 4; let px = Math.round(mid + Math.cos(ang) * r); let py = Math.round(mid + Math.sin(ang) * r); imgOut.setPixel(px, py, c); if (elite) { imgOut.setPixel(Math.round(mid + Math.cos(ang) * (r - 1)), Math.round(mid + Math.sin(ang) * (r - 1)), c) } }
            imgOut.setPixel(mid, mid, 5); imgOut.setPixel(mid - 1, mid, accent); imgOut.setPixel(mid + 1, mid, accent)
        } else {
            for (let d = -r; d <= r; d++) { imgOut.setPixel(mid + d, mid, c); imgOut.setPixel(mid, mid + d, c) }
            imgOut.setPixel(mid, mid, accent); if (elite) { imgOut.setPixel(mid - 1, mid - 1, 5); imgOut.setPixel(mid + 1, mid - 1, 5); imgOut.setPixel(mid - 1, mid + 1, 5); imgOut.setPixel(mid + 1, mid + 1, 5) }
        }
        if (elite) {
            imgOut.setPixel(1, 1, 5); imgOut.setPixel(size - 2, 1, 5)
            imgOut.setPixel(1, size - 2, 5); imgOut.setPixel(size - 2, size - 2, 5)
        }
        let result = polishMinionImage(imgOut, c, type, elite)
        minionImageCache[cacheIndex] = result
        return result
    }
    function minionBaseColor(type: number): number {
        let colors: number[] = [9, 7, 6, 7, 8, 13, 2, 8, 4, 4, 2, 10, 13, 3, 7]
        return colors[type % colors.length]
    }
    export function minionOffscreenMarker(elite: boolean): Image {
        if (elite) return img`
            . 5 .
            5 1 5
            . 5 .
        `
        return img`
            . . .
            . d .
            . . .
        `
    }
    function polishBossImage(type: number, source: Image): Image {
        let out = source.clone()
        if (type == 1) {
            safeEnemyPixel(out, 4, 1, 5); safeEnemyPixel(out, 11, 1, 5)
            safeEnemyPixel(out, 3, 13, 15); safeEnemyPixel(out, 12, 13, 15)
            safeEnemyPixel(out, 7, 5, 1); safeEnemyPixel(out, 8, 10, 13)
        } else if (type == 2) {
            safeEnemyPixel(out, 6, 1, 1); safeEnemyPixel(out, 9, 1, 1)
            safeEnemyPixel(out, 7, 7, 1); safeEnemyPixel(out, 8, 8, 15)
            safeEnemyPixel(out, 6, 14, 9); safeEnemyPixel(out, 9, 14, 8)
        } else if (type == 3) {
            safeEnemyPixel(out, 5, 2, 1); safeEnemyPixel(out, 10, 2, 1)
            safeEnemyPixel(out, 7, 7, 5); safeEnemyPixel(out, 8, 8, 15)
            safeEnemyPixel(out, 3, 10, 12); safeEnemyPixel(out, 12, 10, 12)
        } else if (type == 4) {
            safeEnemyPixel(out, 7, 0, 1); safeEnemyPixel(out, 8, 1, 5)
            safeEnemyPixel(out, 4, 11, 15); safeEnemyPixel(out, 11, 11, 15)
            safeEnemyPixel(out, 7, 7, 5); safeEnemyPixel(out, 8, 8, 2)
        } else if (type == 5) {
            safeEnemyPixel(out, 7, 0, 1); safeEnemyPixel(out, 8, 1, 6)
            safeEnemyPixel(out, 8, 8, 15); safeEnemyPixel(out, 7, 7, 1)
            safeEnemyPixel(out, 3, 7, 6); safeEnemyPixel(out, 13, 9, 6)
        } else {
            safeEnemyPixel(out, 7, 3, 1); safeEnemyPixel(out, 12, 9, 13)
        }
        return out
    }
    export function bossImageForType(type: number): Image {
        let base: Image
        if (type == 1) base = bossWallImage()
        else if (type == 2) base = bossLaserImage()
        else if (type == 3) base = bossDanmakuImage()
        else if (type == 4) base = bossRushImage()
        else if (type == 5) base = bossSummonerImage()
        else base = bossImage()
        return polishBossImage(type, base)
    }
    let bossFrameCache: Image[] = []
    export function bossImageForTypeFrame(type: number, frame: number): Image {
        let f = frame % 2, key = type * 2 + f
        if (bossFrameCache[key] != null) return bossFrameCache[key]
        let source = bossImageForType(type), out: Image
        if (f == 0) out = source
        else {
            out = image.create(source.width, source.height)
            for (let y = 1; y < source.height; y++)for (let x = 0; x < source.width; x++) {
                let c = source.getPixel(x, y)
                if (c != 0) out.setPixel(x, y - 1, c)
            }
        }
        bossFrameCache[key] = out
        return out
    }
    export function trailHueForBossType(type: number): number {
        if (type == 1) return 4
        if (type == 2) return 9
        if (type == 3) return 3
        if (type == 4) return 2
        if (type == 5) return 7
        return 5
    }
    let trailBayer4Pattern: number[] = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5]
    function trailBayer4(x: number, y: number): number {
        let xx = x % 4, yy = y % 4
        if (xx < 0) xx += 4; if (yy < 0) yy += 4
        return trailBayer4Pattern[yy * 4 + xx]
    }
    let trailPaletteR: number[] = [0, 255, 255, 255, 255, 255, 36, 120, 0, 135, 142, 164, 92, 229, 145, 0]
    let trailPaletteG: number[] = [0, 255, 33, 147, 129, 246, 156, 220, 63, 242, 46, 131, 64, 205, 70, 0]
    let trailPaletteB: number[] = [0, 255, 33, 196, 53, 9, 163, 82, 173, 255, 196, 159, 108, 196, 61, 0]
    let trailGradientCache: number[][] = []
    function trailLuma(color: number): number {
        return trailPaletteR[color] * 0.299 + trailPaletteG[color] * 0.587 + trailPaletteB[color] * 0.114
    }
    function trailSaturation(color: number): number {
        let r = trailPaletteR[color], g = trailPaletteG[color], b = trailPaletteB[color]
        let hi = Math.max(r, Math.max(g, b)), lo = Math.min(r, Math.min(g, b))
        if (hi <= 0) return 0
        return (hi - lo) * 100 / hi
    }
    function trailHue(color: number): number {
        let r = trailPaletteR[color] / 255, g = trailPaletteG[color] / 255, b = trailPaletteB[color] / 255
        let hi = Math.max(r, Math.max(g, b)), lo = Math.min(r, Math.min(g, b)), d = hi - lo
        if (d < 0.0001) return 0
        let h = 0
        if (hi == r) h = 60 * ((g - b) / d)
        else if (hi == g) h = 60 * ((b - r) / d + 2)
        else h = 60 * ((r - g) / d + 4)
        while (h < 0) h += 360
        while (h >= 360) h -= 360
        return h
    }
    function trailHueDistance(a: number, b: number): number {
        let d = Math.abs(a - b)
        return d > 180 ? 360 - d : d
    }
    function trailHighlightTarget(edgeColor: number): number {
        if (edgeColor < 1 || edgeColor > 15) edgeColor = 1
        let sourceHue = trailHue(edgeColor), sourceSat = trailSaturation(edgeColor), sourceLuma = trailLuma(edgeColor)
        let best = edgeColor, bestScore = -999999
        for (let c = 1; c <= 14; c++) {
            if (c == edgeColor) continue
            let l = trailLuma(c), sat = trailSaturation(c), h = trailHue(c)
            if (l <= sourceLuma + 8) continue
            let huePenalty = sourceSat >= 35 ? trailHueDistance(sourceHue, h) : 0
            if (sourceSat >= 35 && sat >= 20 && huePenalty > 78) continue
            if (sourceSat >= 35 && sat < 20) huePenalty += 38
            let score = (l - sourceLuma) * 3 - huePenalty * 1.6 - Math.abs(sourceSat - sat) * 0.30
            if (score > bestScore) { bestScore = score; best = c }
        }
        if (best != edgeColor) return best
        for (let c = 1; c <= 14; c++) {
            let score = trailLuma(c) - sourceLuma
            if (score > bestScore) { bestScore = score; best = c }
        }
        return best
    }
    function nearestTrailColor(r: number, g: number, b: number): number {
        let best = 1, bestD = 999999999
        for (let c = 1; c <= 14; c++) {
            let dr = trailPaletteR[c] - r, dg = trailPaletteG[c] - g, db = trailPaletteB[c] - b
            let d = dr * dr * 0.9 + dg * dg * 1.15 + db * db * 0.8
            if (d < bestD) { bestD = d; best = c }
        }
        return best
    }
    export function trailGradientLevelCount(speed: number): number {
        if (speed < 0) speed = 0
        let levels = 2 + Math.floor(speed / 85)
        if (levels < 2) levels = 2
        if (levels > 7) levels = 7
        return levels
    }
    export function buildTrailGradient(edgeColor: number, speed: number): number[] {
        if (edgeColor < 1 || edgeColor > 15) edgeColor = 1
        let levels = trailGradientLevelCount(speed)
        let key = edgeColor * 8 + levels
        if (trailGradientCache[key] != null) return trailGradientCache[key]
        let target = trailHighlightTarget(edgeColor)
        let sr = trailPaletteR[edgeColor], sg = trailPaletteG[edgeColor], sb = trailPaletteB[edgeColor]
        let tr = trailPaletteR[target], tg = trailPaletteG[target], tb = trailPaletteB[target]
        let result: number[] = []
        for (let i = 0; i < levels; i++) {
            let q = levels <= 1 ? 0 : i / (levels - 1)
            let e = q * q * (3 - 2 * q)
            let r = sr + (tr - sr) * e, g = sg + (tg - sg) * e, b = sb + (tb - sb) * e
            result.push(nearestTrailColor(r, g, b))
        }
        trailGradientCache[key] = result
        return result
    }
    export function trailDynamicDitherColor(colors: number[], age01: number, density: number, x: number, y: number): number {
        if (colors == null || colors.length <= 0 || density <= 0) return 0
        if (age01 < 0) age01 = 0; if (age01 > 1) age01 = 1
        if (density > 1) density = 1
        let survive = trailBayer4(x, y)
        let surviveCut = Math.floor(density * 16)
        if (surviveCut < 1) return 0
        if (survive >= surviveCut) return 0
        if (colors.length == 1) return colors[0]
        let colorProgress = age01 / 0.86
        if (colorProgress < 0) colorProgress = 0; if (colorProgress > 1) colorProgress = 1
        let pos = colorProgress * (colors.length - 1)
        let lo = Math.floor(pos), hi = lo + 1
        if (hi >= colors.length) hi = colors.length - 1
        let mix = pos - lo
        let mixBayer = trailBayer4(x + 2, y + 1)
        let mixCut = Math.floor(mix * 16)
        return mixBayer < mixCut ? colors[hi] : colors[lo]
    }
    export function trailMidColorForEdge(edgeColor: number): number {
        let colors = buildTrailGradient(edgeColor, 90)
        return colors.length > 1 ? colors[1] : edgeColor
    }
    export function bossTrailHueForType(type: number): number { return trailHueForBossType(type) }
