    function quantizeDirection16(vx: number, vy: number): number {
        let a = Math.atan2(vy, vx)
        if (a < 0) a += Math.PI * 2
        return Math.round(a / (Math.PI / 8)) % 16
    }
    let bossSwordCache: Image[] = []
    export function bossBulletSword(vx: number, vy: number): Image {
        let dir = quantizeDirection16(vx, vy)
        if (bossSwordCache[dir] != null) return bossSwordCache[dir]
        let angle = dir * Math.PI / 8
        let out = image.create(9, 9)
        let cx = 4, cy = 4
        for (let y = 0; y < 9; y++) {
            for (let x = 0; x < 9; x++) {
                let dx = x - cx, dy = y - cy
                let rx = dx * Math.cos(angle) + dy * Math.sin(angle)
                let ry = 0 - dx * Math.sin(angle) + dy * Math.cos(angle)
                let dOuter = (rx - 0.4) * (rx - 0.4) + ry * ry
                let dInner = (rx + 1.2) * (rx + 1.2) + ry * ry
                if (dOuter <= 11.2 && dInner >= 4.6 && rx >= -3.4 && rx <= 3.6) {
                    out.setPixel(x, y, 9)
                }
            }
        }
        for (let y = 0; y < 9; y++) {
            for (let x = 0; x < 9; x++) {
                if (out.getPixel(x, y) != 9) continue
                let dx = x - cx, dy = y - cy
                let rx = dx * Math.cos(angle) + dy * Math.sin(angle)
                let ry = 0 - dx * Math.sin(angle) + dy * Math.cos(angle)
                let inner = (rx + 1.2) * (rx + 1.2) + ry * ry
                let outer = (rx - 0.4) * (rx - 0.4) + ry * ry
                if (inner < 7.0) out.setPixel(x, y, 1)
                else if (outer > 9.4 || rx > 2.4) out.setPixel(x, y, 5)
            }
        }
        bossSwordCache[dir] = out
        return out
    }
