    export function playerMissile(vx: number, vy: number): Image {
        let ax = Math.abs(vx), ay = Math.abs(vy), dir = 0
        if (ax * 2 < ay) dir = vy < 0 ? 0 : 4
        else if (ay * 2 < ax) dir = vx < 0 ? 6 : 2
        else if (vx < 0 && vy < 0) dir = 7
        else if (vx >= 0 && vy < 0) dir = 1
        else if (vx < 0 && vy >= 0) dir = 5
        else dir = 3
        if (playerMissileImages[dir] == null) playerMissileImages[dir] = buildPlayerMissileImage(dir)
        return playerMissileImages[dir]
    }
