    export function backgroundPanel(style: number, originX: number, originY: number): Image {
        let width = GameConfig.SCREEN_WIDTH + 4
        let height = GameConfig.SCREEN_HEIGHT + 4
        let panel = image.create(width, height)
        panel.fill(15)
        let color = 14
        if (style == 0) {
            for (let baseY = -40; baseY <= GameConfig.WORLD_HEIGHT + 40; baseY += 52) {
                for (let localX = 0; localX < width; localX++) {
                    let worldX = originX + localX
                    let worldY = baseY + Math.round(Math.sin(worldX / 30) * 2)
                    let localY = worldY - originY
                    if (localY >= 0 && localY < height) panel.setPixel(localX, localY, color)
                }
            }
        } else if (style == 1) {
            for (let baseX = -40; baseX <= GameConfig.WORLD_WIDTH + 40; baseX += 52) {
                for (let localY = 0; localY < height; localY++) {
                    let worldY = originY + localY
                    let worldX = baseX + Math.round(Math.sin(worldY / 32) * 2)
                    let localX = worldX - originX
                    if (localX >= 0 && localX < width) panel.setPixel(localX, localY, color)
                }
            }
        } else if (style == 2) {
            for (let base = -GameConfig.WORLD_WIDTH; base <= GameConfig.WORLD_HEIGHT + 80; base += 62) {
                for (let localX = 0; localX < width; localX++) {
                    let worldX = originX + localX
                    let worldY = base + Math.idiv(worldX, 2) + Math.round(Math.sin(worldX / 36) * 2)
                    let localY = worldY - originY
                    if (localY >= 0 && localY < height) panel.setPixel(localX, localY, color)
                }
            }
        } else {
            drawBackgroundWorldLine(panel, originX, originY, 12, 58, 68, 28, color)
            drawBackgroundWorldLine(panel, originX, originY, 68, 28, 126, 74, color)
            drawBackgroundWorldLine(panel, originX, originY, 126, 74, 184, 42, color)
            drawBackgroundWorldLine(panel, originX, originY, 184, 42, 238, 86, color)
            drawBackgroundWorldLine(panel, originX, originY, 238, 86, 306, 50, color)
            drawBackgroundWorldLine(panel, originX, originY, 68, 28, 92, 118, color)
            drawBackgroundWorldLine(panel, originX, originY, 126, 74, 150, 150, color)
            drawBackgroundWorldLine(panel, originX, originY, 184, 42, 205, 132, color)
            drawBackgroundWorldLine(panel, originX, originY, 18, 228, 82, 184, color)
            drawBackgroundWorldLine(panel, originX, originY, 82, 184, 146, 232, color)
            drawBackgroundWorldLine(panel, originX, originY, 146, 232, 212, 192, color)
            drawBackgroundWorldLine(panel, originX, originY, 212, 192, 304, 246, color)
            drawBackgroundWorldLine(panel, originX, originY, 82, 184, 105, 278, color)
            drawBackgroundWorldLine(panel, originX, originY, 212, 192, 244, 288, color)
            let nodeX = [12, 68, 126, 184, 238, 306, 92, 150, 205, 18, 82, 146, 212, 304, 105, 244]
            let nodeY = [58, 28, 74, 42, 86, 50, 118, 150, 132, 228, 184, 232, 192, 246, 278, 288]
            for (let index = 0; index < nodeX.length; index++) {
                drawBackgroundWorldNode(panel, originX, originY, nodeX[index], nodeY[index], color)
            }
        }
        return panel
    }
    function drawBackgroundWorldLine(
        panel: Image, originX: number, originY: number,
        x1: number, y1: number, x2: number, y2: number, color: number
    ) {
        let dx = x2 - x1
        let dy = y2 - y1
        let steps = Math.max(Math.abs(dx), Math.abs(dy))
        if (steps < 1) steps = 1
        for (let step = 0; step <= steps; step++) {
            let worldX = x1 + Math.idiv(dx * step, steps)
            let worldY = y1 + Math.idiv(dy * step, steps)
            let localX = worldX - originX
            let localY = worldY - originY
            if (localX >= 0 && localX < panel.width && localY >= 0 && localY < panel.height) {
                panel.setPixel(localX, localY, color)
            }
        }
    }
    function drawBackgroundWorldNode(
        panel: Image, originX: number, originY: number,
        worldX: number, worldY: number, color: number
    ) {
        let localX = worldX - originX
        let localY = worldY - originY
        if (localX >= 0 && localX < panel.width && localY >= 0 && localY < panel.height) {
            panel.setPixel(localX, localY, color)
        }
    }
