    let wallDartFrames: Image[] = []
    export function bossWallDart(vx: number, vy: number): Image {
        let angle = Math.atan2(vy, vx)
        if (angle < 0) angle += Math.PI * 2
        let direction = Math.round(angle / (Math.PI / 16)) % 32
        if (wallDartFrames[direction] != null) return wallDartFrames[direction]
        let a = direction * Math.PI / 16
        let cs = Math.cos(a), sn = Math.sin(a)
        let out = image.create(9, 9)
        for (let y = 0; y < 9; y++)for (let x = 0; x < 9; x++) {
            let dx = x - 4, dy = y - 4
            let forward = dx * cs + dy * sn
            let sideways = dy * cs - dx * sn
            if (forward < -3.9 || forward > 4.1) continue
            let width = (1 - Math.abs(forward) / 4.2) * 1.7
            if (width < 0 || Math.abs(sideways) > width) continue
            let color = 4
            if (Math.abs(sideways) < width - 0.30) color = 9
            if (Math.abs(sideways) < 0.43 && forward >= -0.5 && forward < 2.5) color = 5
            if (forward >= 3.2) color = 1
            out.setPixel(x, y, color)
        }
        wallDartFrames[direction] = out
        return out
    }
    export function isBossWallDart(imageToCheck: Image): boolean {
        for (let frame of wallDartFrames) if (frame != null && frame == imageToCheck) return true
        return false
    }
