    function danmakuSpecialLeafBase(tier: number): Image {
        if (tier < 0) tier = 0; if (tier > 2) tier = 2
        if (danmakuLeafBaseImages[tier] != null) return danmakuLeafBaseImages[tier]
        let size = 7 + tier * 2, out = image.create(size, size), c = Math.idiv(size, 2)
        for (let y = 0; y < size; y++)for (let x = 0; x < size; x++) {
            let dx = x - c, dy = y - c
            let outer = (dx * dx * 3 + dy * dy * 2) <= c * c * 3
            let inner = ((dx - 1) * (dx - 1) * 3 + dy * dy * 2) <= (Math.max(1, c - 2) * Math.max(1, c - 2) * 3)
            if (outer && !inner && dx + dy <= c + 1) out.setPixel(x, y, (x + y) % 3 == 0 ? 1 : 13)
        }
        out.setPixel(c, c, 5); out.setPixel(size - 2, c, 1); out.setPixel(size - 1, c, 13)
        danmakuLeafBaseImages[tier] = out
        return out
    }
    function rotateCardinal(source: Image, dir4: number): Image {
        dir4 = ((dir4 % 4) + 4) % 4
        if (dir4 == 0) return source
        let size = source.width, out = image.create(size, size)
        for (let y = 0; y < size; y++)for (let x = 0; x < size; x++) {
            let c = source.getPixel(x, y); if (c == 0) continue
            if (dir4 == 1) out.setPixel(size - 1 - y, x, c)
            else if (dir4 == 2) out.setPixel(size - 1 - x, size - 1 - y, c)
            else out.setPixel(y, size - 1 - x, c)
        }
        return out
    }
    export function danmakuSpecialLeaf(tier: number, dir4: number): Image {
        if (tier < 0) tier = 0; if (tier > 2) tier = 2
        dir4 = ((dir4 % 4) + 4) % 4
        let key = tier * 4 + dir4
        if (danmakuLeafCardinalImages[key] != null) return danmakuLeafCardinalImages[key]
        let out = rotateCardinal(danmakuSpecialLeafBase(tier), dir4)
        danmakuLeafCardinalImages[key] = out
        return out
    }
    export function isDanmakuSpecialLeafImage(candidate: Image): boolean {
        if (candidate == null) return false
        for (let i = 0; i < danmakuLeafCardinalImages.length; i++)if (danmakuLeafCardinalImages[i] != null && danmakuLeafCardinalImages[i] == candidate) return true
        return false
    }
