        sprites.onDestroyed(SpriteKind.MinionEffect, function (trail) { forgetTrail(trail) })
        sprites.onDestroyed(SpriteKind.PlayerWingTrailLeft, function (trail) { forgetTrail(trail) })
        sprites.onDestroyed(SpriteKind.PlayerWingTrailRight, function (trail) { forgetTrail(trail) })
        sprites.onDestroyed(SpriteKind.PlayerEngineTrail, function (trail) { forgetTrail(trail) })
