    export function category(patternId: number): number {
        if (patternId == 14 || patternId == 16 || patternId == 31) return CATEGORY_LASER
        if (patternId == 8 || patternId == 17 || patternId == 32) return CATEGORY_SUPPORT
        if (patternId == 15 || patternId == 19 || patternId == 23 || patternId == 26 || patternId == 27 || patternId == 28) return CATEGORY_WALL_EDGE
        return CATEGORY_GENERAL
    }
