        if (patternId == 3) return 1350
        if (patternId == 14 || patternId == 15 || patternId == 28) return 1450
        if (patternId == 4) return 1500
        if (patternId == 1) return 800
        if (patternId == 6) return 850
        if (patternId == 12 || patternId == 13 || patternId == 19 || patternId == 20 || patternId == 21) return 950
