namespace BossPatternLibrary {
    export function patternForBoss(type: number): number {
        if (type == BossRegistry.TYPE_HYBRID) return BossRegistry.SPECIAL_HYBRID
        if (type == BossRegistry.TYPE_WALL) return BossRegistry.SPECIAL_WALL
        if (type == BossRegistry.TYPE_LASER) return BossRegistry.SPECIAL_LASER
        if (type == BossRegistry.TYPE_DANMAKU) return BossRegistry.SPECIAL_DANMAKU
        if (type == BossRegistry.TYPE_RUSH) return BossRegistry.SPECIAL_RUSH
        if (type == BossRegistry.TYPE_SUMMONER) return BossRegistry.SPECIAL_SUMMONER
        return -1
    }
    export function isBossPattern(type: number, patternId: number): boolean { return patternForBoss(type) == patternId }
    export function isOneShot(patternId: number): boolean {
        return patternId == BossRegistry.SPECIAL_HYBRID || patternId == BossRegistry.SPECIAL_DANMAKU || patternId == BossRegistry.SPECIAL_RUSH || patternId == BossRegistry.SPECIAL_WALL
    }
    export function windup(type: number, patternId: number): number {
        if (!isBossPattern(type, patternId)) return 0
        if (patternId == BossRegistry.SPECIAL_RUSH || patternId == BossRegistry.SPECIAL_LASER) return 0
        return 900
    }
    export function recovery(patternId: number): number {
        if (patternId == BossRegistry.SPECIAL_RUSH) return 0
        if (patternId == BossRegistry.SPECIAL_SUMMONER) return 0
        if (patternId == BossRegistry.SPECIAL_HYBRID) return 750
        if (patternId == BossRegistry.SPECIAL_DANMAKU) return 3600
        if (patternId == BossRegistry.SPECIAL_WALL) return 0
        if (patternId == BossRegistry.SPECIAL_LASER) return 0
        return -1
    }
    export function duration(patternId: number): number {
        if (isOneShot(patternId) || patternId == BossRegistry.SPECIAL_SUMMONER) return GameConfig.BOSS_SIGNATURE_EXECUTION_WINDOW_MS
        return -1
    }
    export function usesMainPatternTiming(patternId: number): boolean { return patternId == BossRegistry.SPECIAL_LASER }
    export function usesSingleHardVolley(patternId: number): boolean { return patternId == BossRegistry.SPECIAL_LASER }
    export function firstPickDelayMs(patternId: number): number { return patternId == BossRegistry.SPECIAL_LASER ? 900 : 0 }
}
