            let qb = EnemyFramework.markerProgress1000(now - GameConfig.HYBRID_CORE_SUMMON_STREAK_LAG2_MS, pendingBornAts[i], pendingArriveAts[i])
            if (pendingStreakA[i] != null) pendingStreakA[i].setPosition(EnemyFramework.easedLerp(pendingStartXs[i], tx, qa), EnemyFramework.easedLerp(pendingStartYs[i], ty, qa))
