    let endYs: number[] = []
    let halfWidths: number[] = []
    let specialFlags: boolean[] = []
    let expireAts: number[] = []
    function removeAt(i: number) {
        startXs.removeAt(i); startYs.removeAt(i); endXs.removeAt(i); endYs.removeAt(i)
        halfWidths.removeAt(i); specialFlags.removeAt(i); expireAts.removeAt(i)
    }
    export function clear() {
        startXs = []; startYs = []; endXs = []; endYs = []; halfWidths = []; specialFlags = []; expireAts = []
    }
    export function addRoute(x0: number, y0: number, x1: number, y1: number, halfWidth: number, special: boolean, expireAt: number) {
        if (halfWidth < 2) halfWidth = 2
        startXs.push(x0); startYs.push(y0); endXs.push(x1); endYs.push(y1)
        halfWidths.push(halfWidth); specialFlags.push(special); expireAts.push(expireAt)
    }
    function drawRoute(i: number, cx: number, cy: number, now: number) {
        let wx0 = startXs[i], wy0 = startYs[i], wx1 = endXs[i], wy1 = endYs[i]
        let dx = wx1 - wx0, dy = wy1 - wy0, mag = Math.sqrt(dx * dx + dy * dy)
        if (mag < 0.5) return
        let sx0 = wx0 - cx + GameConfig.SCREEN_WIDTH / 2, sy0 = wy0 - cy + GameConfig.SCREEN_HEIGHT / 2
        let sx1 = wx1 - cx + GameConfig.SCREEN_WIDTH / 2, sy1 = wy1 - cy + GameConfig.SCREEN_HEIGHT / 2
        let bright = specialFlags[i] ? 2 : 5
        let dim = specialFlags[i] ? 4 : 1
        let color = Math.idiv(now, 100) % 2 == 0 ? bright : dim
        screen.drawLine(Math.round(sx0), Math.round(sy0), Math.round(sx1), Math.round(sy1), color)
    }
    function draw() {
        let now = game.runtime(), cx = WorldSystem.getCameraX(), cy = WorldSystem.getCameraY()
        for (let i = startXs.length - 1; i >= 0; i--) {
            if (now >= expireAts[i]) { removeAt(i); continue }
            drawRoute(i, cx, cy, now)
        }
    }
