        dirX.push(1); dirY.push(0); lastSampleX.push(owner == null ? 0 : owner.x); lastSampleY.push(owner == null ? 0 : owner.y); nextTrailShotAts.push(0); lastDistanceAts.push(0)
        dashStartedAts.push(0); arcSprites.push(null); arcBornAts.push(0); arcDetached.push(false)
