        screen.drawLine(x, y - radius, x + radius, y, color); screen.drawLine(x + radius, y, x, y + radius, color)
        screen.drawLine(x, y + radius, x - radius, y, color); screen.drawLine(x - radius, y, x, y - radius, color)
