namespace PatternTriSplitRuntime {
    class SplitEntry {
        bullet: Sprite; generation: number; splitAt: number; hard: boolean
        constructor(bullet: Sprite, generation: number, splitAt: number, hard: boolean) { this.bullet = bullet; this.generation = generation; this.splitAt = splitAt; this.hard = hard }
    }
    let entries: SplitEntry[] = []
    function removeAt(i: number) { if (i < 0 || i >= entries.length) return; let last = entries.length - 1; if (i != last) entries[i] = entries[last]; entries.pop() }
    function register(bullet: Sprite, generation: number, splitAt: number, hard: boolean) { if (bullet != null) entries.push(new SplitEntry(bullet, generation, splitAt, hard)) }
    export function clear() { entries = [] }
    export function start(owner: Sprite, player: Sprite, hard: boolean) {
        if (owner == null || player == null) return
        let dx = player.x - owner.x, dy = player.y - owner.y, d = Math.sqrt(dx * dx + dy * dy); if (d < 1) d = 1
        let speed = hard ? 42 : 36
        let mother = BulletPatternSystem.makeDirectBullet(owner.x, owner.y, dx / d * speed, dy / d * speed, GameAssets.bossTripleSplitImage(0, hard, 0), 0)
        if (mother != null) register(mother, 0, game.runtime() + Math.round(d / speed * 1000), hard)
    }
    export function update() {
        let now = game.runtime()
        for (let i = entries.length - 1; i >= 0; i--) {
            let e = entries[i], source = e == null ? null : e.bullet
            if (source == null) { removeAt(i); continue }
            if (WorldSystem.isSpriteOnCamera(source, 0)) source.setImage(GameAssets.bossTripleSplitImage(e.generation, e.hard, Math.idiv(now, 120) % 2))
            if (now < e.splitAt) continue
            let x = source.x, y = source.y, generation = e.generation, hard = e.hard
            removeAt(i); source.destroy()
            let fx = sprites.create(GameAssets.bossTripleSplitBurst(generation, hard), SpriteKind.BossTelegraph)
            fx.setFlag(SpriteFlag.Ghost, true); fx.setFlag(SpriteFlag.AutoDestroy, false); fx.z = GameConfig.BOSS_BULLET_Z - 1; fx.setPosition(x, y); fx.lifespan = 140
            if (generation == 0) spawnRing(x, y, hard ? 7 : (BulletPatternSystem.level() >= 20 ? 6 : 5), hard ? 43 : 39, 1, hard, 680)
            else if (generation == 1) spawnRing(x, y, hard ? 3 : 2, hard ? 50 : 46, 2, hard, 560)
            else spawnFinalRing(x, y, 2, hard ? 60 : 55, hard)
        }
    }
    function spawnRing(x: number, y: number, count: number, speed: number, generation: number, hard: boolean, travelMs: number) {
        let offset = randint(0, 359)
        for (let i = 0; i < count; i++) {
            let angle = offset + i * 360 / count, r = angle * Math.PI / 180
            let child = BulletPatternSystem.makeDirectBullet(x, y, Math.cos(r) * speed, Math.sin(r) * speed, GameAssets.bossTripleSplitImage(generation, hard, 0), 0)
            if (child != null) register(child, generation, game.runtime() + travelMs, hard)
        }
    }
    function spawnFinalRing(x: number, y: number, count: number, speed: number, hard: boolean) {
        let offset = randint(0, 359)
        for (let i = 0; i < count; i++) { let angle = offset + i * 360 / count, r = angle * Math.PI / 180; BossSystem.queuePatternBullet(x, y, Math.cos(r) * speed, Math.sin(r) * speed, GameAssets.bossTripleSplitImage(3, hard, 0), 0, false, 0) }
    }
    export function forget(bullet: Sprite) { if (bullet == null) return; for (let i = entries.length - 1; i >= 0; i--)if (entries[i] != null && entries[i].bullet == bullet) { removeAt(i); return } }
}
