            this.grazeCount = 0
            this.grazeScore = 0
            this.shieldCancelCount = 0
            this.shieldCancelScore = 0
            this.bulletClearCount = 0
            this.bulletClearScore = 0
            this.minionKillCount = 0
            this.shieldMinionKillCount = 0
            this.minionKillScore = 0
            this.bossBaseScore = 0
            this.bossTimeScore = 0
