namespace WorldSystem {
    let cameraX = GameConfig.SCREEN_WIDTH / 2
    let cameraY = GameConfig.SCREEN_HEIGHT / 2
    let backgroundPanels: Sprite[] = []
    let backgroundBaseX: number[] = []
    let backgroundBaseY: number[] = []
    let backgroundOriginX: number[] = []
    let backgroundOriginY: number[] = []
    let backgroundDriftStep = 0
    let currentBackgroundStyle = -1
    export function init() {
        scene.setBackgroundColor(15)
        createWorldBackground()
        GameUpdateScheduler.everyFrame(function () {
            updateWorld()
        })
        GameUpdateScheduler.every(GameConfig.BACKGROUND_DRIFT_INTERVAL_MS, function () {
            updateBackgroundDrift()
        })
        GameUpdateScheduler.every(GameConfig.PROJECTILE_CLEANUP_INTERVAL_MS, function () {
            cleanupProjectiles()
        })
    }
    export function getCameraX(): number {
        return cameraX
    }
    export function getCameraY(): number {
        return cameraY
    }
    export function isSpriteOnCamera(sprite: Sprite, margin?: number): boolean {
        if (sprite == null) return false
        let m = margin == null ? 0 : margin
        let left = cameraX - GameConfig.SCREEN_WIDTH / 2 - m
        let right = cameraX + GameConfig.SCREEN_WIDTH / 2 + m
        let top = cameraY - GameConfig.SCREEN_HEIGHT / 2 - m
        let bottom = cameraY + GameConfig.SCREEN_HEIGHT / 2 + m
        return sprite.right >= left && sprite.left <= right && sprite.bottom >= top && sprite.top <= bottom
    }
    function createWorldBackground() {
        backgroundPanels = []
        backgroundBaseX = []
        backgroundBaseY = []
        backgroundOriginX = []
        backgroundOriginY = []
        backgroundDriftStep = 0
        currentBackgroundStyle = -1
        for (let row = 0; row < 3; row++) {
            for (let column = 0; column < 2; column++) {
                let baseX = 80 + column * GameConfig.SCREEN_WIDTH
                let baseY = 60 + row * GameConfig.SCREEN_HEIGHT
                let originX = column * GameConfig.SCREEN_WIDTH - 2
                let originY = row * GameConfig.SCREEN_HEIGHT - 2
                let panel = sprites.create(
                    GameAssets.backgroundPanel(0, originX, originY),
                    SpriteKind.WorldBackground
                )
                panel.z = GameConfig.WORLD_BACKGROUND_Z
                panel.setFlag(SpriteFlag.Ghost, true)
                panel.setPosition(baseX, baseY)
                backgroundPanels.push(panel)
                backgroundBaseX.push(baseX)
                backgroundBaseY.push(baseY)
                backgroundOriginX.push(originX)
                backgroundOriginY.push(originY)
            }
        }
    }
    export function randomizeBackgroundForStage() {
        if (backgroundPanels.length == 0) return
        let nextStyle = randint(0, GameConfig.BACKGROUND_STYLE_COUNT - 1)
        if (GameConfig.BACKGROUND_STYLE_COUNT > 1 && nextStyle == currentBackgroundStyle) {
            nextStyle = (nextStyle + 1 + randint(0, GameConfig.BACKGROUND_STYLE_COUNT - 2)) % GameConfig.BACKGROUND_STYLE_COUNT
        }
        currentBackgroundStyle = nextStyle
        backgroundDriftStep = 0
        for (let index = 0; index < backgroundPanels.length; index++) {
            backgroundPanels[index].setImage(
                GameAssets.backgroundPanel(
                    currentBackgroundStyle,
                    backgroundOriginX[index],
                    backgroundOriginY[index]
                )
            )
            backgroundPanels[index].setPosition(backgroundBaseX[index], backgroundBaseY[index])
        }
    }
    function updateBackgroundDrift() {
        if (backgroundPanels.length == 0) return
        backgroundDriftStep = (backgroundDriftStep + 1) % 8
        let dx = 0
        let dy = 0
        if (backgroundDriftStep == 1) { dx = 1; dy = 1 }
        else if (backgroundDriftStep == 2) { dx = 2; dy = 0 }
        else if (backgroundDriftStep == 3) { dx = 1; dy = -1 }
        else if (backgroundDriftStep == 4) { dx = 0; dy = -2 }
        else if (backgroundDriftStep == 5) { dx = -1; dy = -1 }
        else if (backgroundDriftStep == 6) { dx = -2; dy = 0 }
        else if (backgroundDriftStep == 7) { dx = -1; dy = 1 }
        for (let index = 0; index < backgroundPanels.length; index++) {
            backgroundPanels[index].setPosition(
                backgroundBaseX[index] + dx,
                backgroundBaseY[index] + dy
            )
        }
    }
    function updateWorld() {
        let player = PlayerSystem.getPlayer()
        let core = PlayerSystem.getCore()
        if (player.left <= 0) {
            player.left = 0
            if (player.vx < 0) player.vx = 0
        }
        if (player.right >= GameConfig.WORLD_WIDTH) {
            player.right = GameConfig.WORLD_WIDTH
            if (player.vx > 0) player.vx = 0
        }
        if (player.top <= 0) {
            player.top = 0
            if (player.vy < 0) player.vy = 0
        }
        if (player.bottom >= GameConfig.WORLD_HEIGHT) {
            player.bottom = GameConfig.WORLD_HEIGHT
            if (player.vy > 0) player.vy = 0
        }
        core.setPosition(player.x, player.y)
        updateCamera(player)
    }
    function updateCamera(player: Sprite) {
        cameraX = Math.round(player.x)
        cameraY = Math.round(player.y)
        let halfScreenWidth = GameConfig.SCREEN_WIDTH / 2
        let halfScreenHeight = GameConfig.SCREEN_HEIGHT / 2
        if (cameraX < halfScreenWidth) {
            cameraX = halfScreenWidth
        }
        if (cameraX > GameConfig.WORLD_WIDTH - halfScreenWidth) {
            cameraX = GameConfig.WORLD_WIDTH - halfScreenWidth
        }
        if (cameraY < halfScreenHeight) {
            cameraY = halfScreenHeight
        }
        if (cameraY > GameConfig.WORLD_HEIGHT - halfScreenHeight) {
            cameraY = GameConfig.WORLD_HEIGHT - halfScreenHeight
        }
        scene.centerCameraAt(cameraX, cameraY)
    }
    function cleanupProjectiles() {
        cleanupBullets(SpriteKind.PlayerBullet)
        cleanupBullets(SpriteKind.BossBullet)
    }
    function cleanupBullets(kind: number) {
        let bullets = sprites.allOfKind(kind)
        let worldMargin = GameConfig.BULLET_WORLD_MARGIN
        for (let bullet of bullets) {
            if (kind == SpriteKind.BossBullet && GameAssets.isDanmakuSpecialLeafImage(bullet.image)) {
                continue
            }
            if (kind == SpriteKind.BossBullet && BulletPatternSystem.isMegaBullet(bullet)) {
                let bodyOutsideWorld = bullet.right < 0 || bullet.left > GameConfig.WORLD_WIDTH || bullet.bottom < 0 || bullet.top > GameConfig.WORLD_HEIGHT
                if (bodyOutsideWorld && !TrailRibbonSystem.hasOwnerTrailInRect(bullet, 0, GameConfig.WORLD_WIDTH, 0, GameConfig.WORLD_HEIGHT)) bullet.destroy()
                continue
            }
            if (
                bullet.x < -worldMargin ||
                bullet.x > GameConfig.WORLD_WIDTH + worldMargin ||
                bullet.y < -worldMargin ||
                bullet.y > GameConfig.WORLD_HEIGHT + worldMargin
            ) bullet.destroy()
        }
    }
}
namespace PlayerDeathSystem {
    let active = false
    let hitHoldUntil = 0
    let sequenceStartedAt = 0
    let explosion: Sprite = null
    let explosionFrame = -1
    let lastDeathX = 0
    let lastDeathY = 0
    let deathFrames: Image[] = []
    let respawnFrames: Image[] = []
    export function reset() {
        active = false; hitHoldUntil = 0; sequenceStartedAt = 0; explosionFrame = -1; lastDeathX = 0; lastDeathY = 0
        if (explosion != null) explosion.destroy()
        explosion = null
    }
    export function begin(x: number, y: number) {
        lastDeathX = x; lastDeathY = y
        active = true
        sequenceStartedAt = game.runtime()
        hitHoldUntil = sequenceStartedAt + GameConfig.PLAYER_DEATH_HIT_HOLD_MS
        if (explosion != null) explosion.destroy()
        explosion = null; explosionFrame = -1
        ScoreLifeBurstSystem.triggerPlayerDeathClear(x, y)
    }
    export function cancelKeepPosition() {
        active = false; hitHoldUntil = 0; sequenceStartedAt = 0; explosionFrame = -1
        if (explosion != null) explosion.destroy()
        explosion = null
    }
    export function isActive(): boolean { return active }
    export function isHoldingHitFrame(): boolean { return active && hitHoldUntil > 0 && game.runtime() < hitHoldUntil }
    export function getLastDeathX(): number { return lastDeathX }
    export function getLastDeathY(): number { return lastDeathY }
    function baseExplosionFrame(frame: number): Image {
        if (frame <= 0) return GameAssets.playerDeathExplosionFrame1()
        if (frame == 1) return GameAssets.playerDeathExplosionFrame2()
        if (frame == 2) return GameAssets.playerDeathExplosionFrame3()
        return GameAssets.playerDeathExplosionFrame4()
    }
    function buildDeathFrame(frame: number): Image {
        if (frame < 0) frame = 0; if (frame > 6) frame = 6
        if (deathFrames[frame] != null) return deathFrames[frame]
        let size = 35, c = 17, out = image.create(size, size)
        let base = baseExplosionFrame(frame <= 1 ? frame : (frame <= 3 ? 2 : 3))
        out.drawTransparentImage(base, Math.idiv(size - base.width, 2), Math.idiv(size - base.height, 2))
        let r1 = 5 + frame * 2
        let r2 = Math.max(2, r1 - 4)
        for (let y = 0; y < size; y++)for (let x = 0; x < size; x++) {
            let dx = x - c, dy = y - c, d2 = dx * dx + dy * dy
            let ring1 = d2 <= r1 * r1 && d2 >= (r1 - 1) * (r1 - 1)
            let ring2 = frame >= 2 && d2 <= r2 * r2 && d2 >= (r2 - 1) * (r2 - 1)
            if (ring1) {
                let keep = 7 - frame
                if (((x * 3 + y * 5 + frame * 7) & 7) < keep) out.setPixel(x, y, frame < 2 ? 1 : (frame < 5 ? 5 : 4))
            } else if (ring2) {
                if (((x * 5 + y * 3 + frame) & 3) < 2) out.setPixel(x, y, frame < 4 ? 9 : 5)
            }
        }
        let dxs: number[] = [1, 1, 0, -1, -1, -1, 0, 1]
        let dys: number[] = [0, 1, 1, 1, 0, -1, -1, -1]
        let shardStart = 5 + frame
        let shardEnd = 8 + frame * 3
        if (shardEnd > 16) shardEnd = 16
        for (let d = 0; d < 8; d++) {
            for (let step = shardStart; step <= shardEnd; step += 2) {
                let px = c + dxs[d] * step, py = c + dys[d] * step
                if (px < 0 || py < 0 || px >= size || py >= size) continue
                if (((step + d + frame) & 3) == 0) continue
                out.setPixel(px, py, d % 2 == 0 ? 4 : 5)
            }
        }
        if (frame <= 1) {
            out.setPixel(c, c, 1); out.setPixel(c - 1, c, 1); out.setPixel(c + 1, c, 1); out.setPixel(c, c - 1, 1); out.setPixel(c, c + 1, 1)
        } else if (frame <= 4) {
            out.setPixel(c, c, 5)
        }
        deathFrames[frame] = out
        return out
    }
    function setExplosionFrame(frame: number) {
        if (explosion == null || frame == explosionFrame) return
        explosionFrame = frame
        explosion.setImage(buildDeathFrame(frame))
        explosion.setPosition(lastDeathX, lastDeathY)
    }
    function buildRespawnFrame(frame: number): Image {
        if (frame < 0) frame = 0; if (frame > 7) frame = 7
        if (respawnFrames[frame] != null) return respawnFrames[frame]
        let size = 45, c = 22, out = image.create(size, size)
        let radius = 4 + frame * 2
        let inner = Math.max(1, radius - 2)
        for (let y = 0; y < size; y++)for (let x = 0; x < size; x++) {
            let dx = x - c, dy = y - c, d2 = dx * dx + dy * dy
            if (d2 <= radius * radius && d2 > inner * inner) {
                if (((x * 3 + y * 5 + frame) & 3) != 0) out.setPixel(x, y, frame < 3 ? 9 : (frame < 6 ? 6 : 1))
            }
        }
        let rayStart = Math.max(2, radius - 1), rayEnd = Math.min(20, radius + 3)
        for (let d = rayStart; d <= rayEnd; d += 2) {
            out.setPixel(c + d, c, 9); out.setPixel(c - d, c, 9); out.setPixel(c, c + d, 9); out.setPixel(c, c - d, 9)
        }
        respawnFrames[frame] = out
        return out
    }
    export function showRespawnBurst(x: number, y: number) {
        control.runInParallel(function () {
            let fx = sprites.create(buildRespawnFrame(0), SpriteKind.Hud)
            fx.setFlag(SpriteFlag.Ghost, true); fx.z = GameConfig.BOSS_BULLET_Z + 24
            fx.setPosition(x, y)
            for (let frame = 0; frame < 8; frame++) {
                fx.setImage(buildRespawnFrame(frame)); fx.setPosition(x, y); pause(28)
            }
            fx.destroy()
        })
    }
    export function update() {
        if (!active || sequenceStartedAt <= 0) return
        let now = game.runtime(), age = now - sequenceStartedAt
        if (age < 0) age = 0
        let player = PlayerSystem.getPlayer(), core = PlayerSystem.getCore()
        if (age < GameConfig.PLAYER_DEATH_HIT_HOLD_MS) {
            if (player != null) { player.vx = 0; player.vy = 0; player.setFlag(SpriteFlag.Invisible, false) }
            if (core != null) core.setFlag(SpriteFlag.Invisible, false)
            return
        }
        if (explosion == null) {
            if (player != null) player.setFlag(SpriteFlag.Invisible, true)
            if (core != null) core.setFlag(SpriteFlag.Invisible, true)
            explosion = sprites.create(buildDeathFrame(0), SpriteKind.Hud)
            explosion.setFlag(SpriteFlag.Ghost, true); explosion.z = GameConfig.BOSS_BULLET_Z + 20
            explosion.setPosition(lastDeathX, lastDeathY); explosionFrame = 0
            scene.cameraShake(3, 140)
        }
        let fxAge = age - GameConfig.PLAYER_DEATH_HIT_HOLD_MS
        if (fxAge < GameConfig.PLAYER_DEATH_ANIMATION_MS) {
            let frame = Math.idiv(fxAge * 7, GameConfig.PLAYER_DEATH_ANIMATION_MS)
            if (frame < 0) frame = 0; if (frame > 6) frame = 6
            setExplosionFrame(frame)
        } else {
            if (explosion != null) explosion.destroy()
            explosion = null; explosionFrame = -1
            if (fxAge < GameConfig.PLAYER_DEATH_ANIMATION_MS + GameConfig.PLAYER_DEATH_RESPAWN_GAP_MS) return
            active = false; hitHoldUntil = 0; sequenceStartedAt = 0
            PlayerSystem.finishDeathSequenceFromModule(lastDeathX, lastDeathY)
        }
    }
}
