            if (adx > 0) scale = ew / adx
            if (ady > 0) { let sy = eh / ady; if (sy < scale) scale = sy }
            ind.setFlag(SpriteFlag.Invisible, false)
            ind.x = hw + dx * scale; ind.y = hh + dy * scale
