namespace MinionCatalog {
    export const GHOST = 0
    export const BAT = 1
    export const WALKER = 2
    export const SLIME = 3
    export const EYE = 4
    export const MOTH = 5
    export const BEETLE = 6
    export const JELLY = 7
    export const SPIDER = 8
    export const CRAB = 9
    export const BOMBER = 10
    export const WISP = 11
    export const MASK = 12
    export const FLOWER = 13
    export const MEDIC = 14
    export function baseHP(type: number): number {
        let hp: number[] = [8, 2, 3, 3, 3, 2, 5, 3, 3, 6, 3, 2, 3, 3, 2]
        return hp[type % hp.length]
    }
    export function visionRange(type: number, elite: boolean): number {
        let ranges: number[] = [42, 78, 64, 42, 92, 84, 62, 76, 84, 72, 48, 76, 86, 80, 68]
        let range = ranges[type % ranges.length]
        if (elite) range += 10
        return range
    }
    export function requiresPlayerAttackRange(type: number): boolean {
        if (type == JELLY || type == FLOWER || type == GHOST || type == SLIME || type == BEETLE) return false
        return true
    }
    export function requiresPlayerMovementRange(type: number, elite: boolean): boolean {
        if (type == BAT || type == EYE || type == MOTH || type == SPIDER || type == CRAB || type == BOMBER || type == WISP || type == MASK) return true
        if (type == WALKER && elite) return true
        return false
    }
    export function affinityForBoss(type: number): number {
        if (type == 1) return SPIDER
        if (type == 2) return EYE
        if (type == 3) return FLOWER
        if (type == 4) return BEETLE
        if (type == 5) return SLIME
        return MASK
    }
}
namespace MinionRuntimeSystem {
    export class MinionRuntime {
        sprite: Sprite
        type: number
        elite: boolean
        hp: number
        maxHP: number
        splitGeneration: number
        healthBar: Sprite
        nextAttackAt: number
        bornAt: number
        spawnReadyAt: number
        spawnWaveTier: number
        difficultyLevel: number
        bossSupport: boolean
        lastEliteTrailAt: number
        lastEliteTrailX: number
        lastEliteTrailY: number
        stateA: number
        stateB: number
        burstVX: number
        burstVY: number
        visualFrame: number
        lastVisualAt: number
        ownerBoss: Sprite
        summoned: boolean
        hardSummoned: boolean
        countsTowardStageTarget: boolean
        hitResponseTargetX: number
        hitResponseTargetY: number
        hitResponseRemaining: number
        hitResponseLastX: number
        hitResponseLastY: number
        attackVolleyCount: number
        attackVolleyTarget: number
        constructor(actor: Sprite, type: number, elite: boolean, hp: number, owner: Sprite, isSummoned: boolean, countsForTarget: boolean, splitGeneration: number, waveTier: number, difficultyStage: number, isBossSupport: boolean, readyAt: number, hiddenDuringTelegraph: boolean, isHardSummon: boolean) {
            this.sprite = actor
            this.type = type
            this.elite = elite
            this.hp = hp
            this.maxHP = hp
            this.splitGeneration = splitGeneration
            this.healthBar = sprites.create(image.create(elite ? 17 : 13, 2), SpriteKind.MinionHealth)
            this.healthBar.setFlag(SpriteFlag.Ghost, true)
            this.healthBar.setFlag(SpriteFlag.AutoDestroy, false)
            this.healthBar.z = actor.z + 2
            this.healthBar.setFlag(SpriteFlag.Invisible, true)
            let born = game.runtime()
            if (readyAt < born) readyAt = born
            this.nextAttackAt = readyAt + randint(500, 1000)
            this.bornAt = born
            this.spawnReadyAt = readyAt
            this.spawnWaveTier = waveTier
            this.difficultyLevel = Math.max(1, difficultyStage)
            this.bossSupport = isBossSupport
            this.lastEliteTrailAt = 0
            this.lastEliteTrailX = actor.x
            this.lastEliteTrailY = actor.y
            this.stateA = randint(0, 359)
            this.stateB = hiddenDuringTelegraph ? -1 : 0
            this.burstVX = 0
            this.burstVY = 0
            this.visualFrame = 0
            this.lastVisualAt = born
            this.ownerBoss = owner
            this.summoned = isSummoned
            this.hardSummoned = isHardSummon
            this.countsTowardStageTarget = countsForTarget
            this.hitResponseTargetX = actor.x
            this.hitResponseTargetY = actor.y
            this.hitResponseRemaining = 0
            this.hitResponseLastX = actor.x
            this.hitResponseLastY = actor.y
            this.attackVolleyCount = 0
            this.attackVolleyTarget = 0
        }
    }
    let runtimes: MinionRuntime[] = []
    export function reset() { runtimes = [] }
    export function add(runtime: MinionRuntime): number { runtimes.push(runtime); return runtimes.length - 1 }
    export function removeAtSwap(index: number): MinionRuntime {
        if (index < 0 || index >= runtimes.length) return null
        let removed = runtimes[index], last = runtimes.length - 1
        if (index != last) runtimes[index] = runtimes[last]
        runtimes.pop()
        return removed
    }
    export function count(): number { return runtimes.length }
    export function get(index: number): MinionRuntime { return index >= 0 && index < runtimes.length ? runtimes[index] : null }
    export function indexOfSprite(actor: Sprite): number {
        if (actor == null) return -1
        for (let i = 0; i < runtimes.length; i++)if (runtimes[i] != null && runtimes[i].sprite == actor) return i
        return -1
    }
}
namespace MinionBehaviorShared {
    export function minX(a: Sprite): number { return Math.idiv(a.width + 1, 2) + GameConfig.MINION_WORLD_ROUTE_MARGIN }
    export function maxX(a: Sprite): number { return GameConfig.WORLD_WIDTH - Math.idiv(a.width + 1, 2) - GameConfig.MINION_WORLD_ROUTE_MARGIN }
    export function minY(a: Sprite): number { return Math.idiv(a.height + 1, 2) + GameConfig.MINION_WORLD_ROUTE_MARGIN }
    export function maxY(a: Sprite): number { return GameConfig.WORLD_HEIGHT - Math.idiv(a.height + 1, 2) - GameConfig.MINION_WORLD_ROUTE_MARGIN }
    export function steerVelocity(a: Sprite, targetVX: number, targetVY: number, blend: number) {
        if (blend < 0) blend = 0
        if (blend > 1) blend = 1
        let loX = minX(a), hiX = maxX(a), loY = minY(a), hiY = maxY(a)
        if (a.x <= loX && targetVX < 0) targetVX = Math.abs(targetVX)
        else if (a.x >= hiX && targetVX > 0) targetVX = 0 - Math.abs(targetVX)
        if (a.y <= loY && targetVY < 0) targetVY = Math.abs(targetVY)
        else if (a.y >= hiY && targetVY > 0) targetVY = 0 - Math.abs(targetVY)
        let nextVX = a.vx * (1 - blend) + targetVX * blend
        let nextVY = a.vy * (1 - blend) + targetVY * blend
        let lookahead = GameConfig.MINION_ROUTE_LOOKAHEAD_MS
        let leftSpeed = Math.max(0, a.x - loX) * 1000 / lookahead
        let rightSpeed = Math.max(0, hiX - a.x) * 1000 / lookahead
        let upSpeed = Math.max(0, a.y - loY) * 1000 / lookahead
        let downSpeed = Math.max(0, hiY - a.y) * 1000 / lookahead
        if (nextVX < 0 && 0 - nextVX > leftSpeed) nextVX = 0 - leftSpeed
        if (nextVX > 0 && nextVX > rightSpeed) nextVX = rightSpeed
        if (nextVY < 0 && 0 - nextVY > upSpeed) nextVY = 0 - upSpeed
        if (nextVY > 0 && nextVY > downSpeed) nextVY = downSpeed
        a.vx = nextVX; a.vy = nextVY
    }
    export function setVel(a: Sprite, vx: number, vy: number, max: number) {
        let d = Math.sqrt(vx * vx + vy * vy)
        if (d > max && d > 0) { vx = vx / d * max; vy = vy / d * max }
        steerVelocity(a, vx, vy, 0.20)
    }
    export function moveCurvedPursuit(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, forwardSpeed: number, curveSpeed: number, blend: number) {
        let phase = (game.runtime() + r.stateA * 23) * Math.PI / 760
        let side = Math.sin(phase)
        steerVelocity(r.sprite, nx * forwardSpeed - ny * curveSpeed * side, ny * forwardSpeed + nx * curveSpeed * side, blend)
    }
    export function keepDistance(a: Sprite, nx: number, ny: number, dist: number, wanted: number, speed: number) {
        let dir = dist > wanted + 8 ? 1 : (dist < wanted - 8 ? -1 : 0)
        steerVelocity(a, nx * speed * dir, ny * speed * dir, 0.18)
    }
    export function moveAlongNearestEdge(a: Sprite, p: Sprite, speed: number) {
        let cx = WorldSystem.getCameraX(), cy = WorldSystem.getCameraY()
        let left = cx - 72, right = cx + 72, top = cy - 52, bottom = cy + 52
        let dl = Math.abs(a.x - left), dr = Math.abs(a.x - right), dt = Math.abs(a.y - top), db = Math.abs(a.y - bottom)
        let m = Math.min(Math.min(dl, dr), Math.min(dt, db))
        let tx = 0, ty = 0
        if (m == dl) { tx = (left - a.x) * 2.0; ty = (p.y > a.y ? 1 : -1) * speed }
        else if (m == dr) { tx = (right - a.x) * 2.0; ty = (p.y > a.y ? 1 : -1) * speed }
        else if (m == dt) { ty = (top - a.y) * 2.0; tx = (p.x > a.x ? 1 : -1) * speed }
        else { ty = (bottom - a.y) * 2.0; tx = (p.x > a.x ? 1 : -1) * speed }
        steerVelocity(a, tx, ty, 0.16)
    }
    export function wander(r: MinionRuntimeSystem.MinionRuntime, speed: number) {
        let phase = (game.runtime() + r.stateA * 31) * Math.PI / 1800
        steerVelocity(r.sprite, Math.cos(phase) * speed, Math.sin(phase * 0.83) * speed, 0.10)
    }
    export function nudgeBackFromWorldEdge(a: Sprite, speed: number) {
        if (a == null) return
        let edge = 10, tx = a.vx, ty = a.vy, needs = false
        if (a.x < edge) { tx = Math.max(tx, speed); needs = true }
        else if (a.x > GameConfig.WORLD_WIDTH - edge) { tx = Math.min(tx, -speed); needs = true }
        if (a.y < edge) { ty = Math.max(ty, speed); needs = true }
        else if (a.y > GameConfig.WORLD_HEIGHT - edge) { ty = Math.min(ty, -speed); needs = true }
        if (needs) steerVelocity(a, tx, ty, 0.18)
    }
    export function scaledAttackCooldown(baseMs: number, waveTier: number, difficultyStage: number): number {
        let stage = EnemyFramework.clampStage30(difficultyStage)
        let stageReduce = Math.idiv((stage - 1) * 18, 29)
        let reduce = Math.max(0, waveTier) * 5 + stageReduce
        if (reduce > 45) reduce = 45
        return Math.idiv(baseMs * (100 - reduce), 100)
    }
    export function scheduleNextAttack(r: MinionRuntimeSystem.MinionRuntime, now: number, normalCooldown: number): number {
        if (r == null || r.sprite == null) return now + Math.max(1, normalCooldown)
        if (r.hardSummoned) normalCooldown = Math.max(1, Math.idiv(normalCooldown * GameConfig.SUMMONER_HARD_ATTACK_INTERVAL_PERCENT, 100))
        if (r.attackVolleyTarget <= 0) r.attackVolleyTarget = randint(GameConfig.MINION_ATTACK_BURST_MIN, GameConfig.MINION_ATTACK_BURST_MAX)
        r.attackVolleyCount += 1
        let extraRest = 0
        if (r.attackVolleyCount >= r.attackVolleyTarget) {
            r.attackVolleyCount = 0
            r.attackVolleyTarget = randint(GameConfig.MINION_ATTACK_BURST_MIN, GameConfig.MINION_ATTACK_BURST_MAX)
            extraRest = randint(GameConfig.MINION_ATTACK_REST_MIN_MS, GameConfig.MINION_ATTACK_REST_MAX_MS)
        }
        return now + Math.max(1, normalCooldown) + extraRest
    }
    export function triggerHitResponse(r: MinionRuntimeSystem.MinionRuntime) {
        if (r == null || r.sprite == null) return
        let p = PlayerSystem.getPlayer(); if (p == null) return
        let dx = p.x - r.sprite.x, dy = p.y - r.sprite.y, dist = Math.sqrt(dx * dx + dy * dy)
        if (dist <= MinionCatalog.visionRange(r.type, r.elite)) return
        r.hitResponseTargetX = p.x; r.hitResponseTargetY = p.y
        r.hitResponseRemaining += GameConfig.MINION_HIT_RESPONSE_DISTANCE_PER_HIT
        if (r.hitResponseRemaining > GameConfig.MINION_HIT_RESPONSE_DISTANCE_CAP) r.hitResponseRemaining = GameConfig.MINION_HIT_RESPONSE_DISTANCE_CAP
        r.hitResponseLastX = r.sprite.x; r.hitResponseLastY = r.sprite.y
    }
    export function updateHitResponse(r: MinionRuntimeSystem.MinionRuntime, speedScale: number): boolean {
        if (r == null || r.sprite == null || r.hitResponseRemaining <= 0) return false
        let a = r.sprite
        let movedX = a.x - r.hitResponseLastX, movedY = a.y - r.hitResponseLastY
        let moved = Math.sqrt(movedX * movedX + movedY * movedY)
        if (moved > 0) { r.hitResponseRemaining -= moved; if (r.hitResponseRemaining < 0) r.hitResponseRemaining = 0 }
        r.hitResponseLastX = a.x; r.hitResponseLastY = a.y
        if (r.hitResponseRemaining <= 0) return false
        let dx = r.hitResponseTargetX - a.x, dy = r.hitResponseTargetY - a.y, d = Math.sqrt(dx * dx + dy * dy)
        if (d <= 4) { r.hitResponseRemaining = 0; return false }
        let speed = GameConfig.MINION_HIT_RESPONSE_SPEED * speedScale
        steerVelocity(a, dx / d * speed, dy / d * speed, 0.24)
        return true
    }
    export function fireBullet(x: number, y: number, vx: number, vy: number, img: Image) {
        let bullet = sprites.create(img, SpriteKind.BossBullet)
        bullet.z = GameConfig.BOSS_BULLET_Z
        bullet.setFlag(SpriteFlag.AutoDestroy, false)
        bullet.setPosition(x, y); bullet.vx = vx; bullet.vy = vy
    }
}
namespace MinionGhostBehavior {
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, speed: number) {
        MinionBehaviorShared.moveCurvedPursuit(r, nx, ny, 24 * speed, 7 * speed, 0.19)
    }
}
namespace MinionBatBehavior {
    function fire(a: Sprite, elite: boolean, phase: number) {
        let dx = a.vx, dy = a.vy, d = Math.sqrt(dx * dx + dy * dy)
        if (d < 1) { let angle = (phase % 8) * Math.PI / 4; dx = Math.cos(angle); dy = Math.sin(angle); d = 1 }
        let nx = dx / d, ny = dy / d, px = -ny, py = nx
        let side = phase % 2 == 0 ? 1 : -1
        let spawnOffset = elite ? 7 : 5
        let forward = elite ? 58 : 52
        let inward = (elite ? 19 : 15) * side
        MinionBehaviorShared.fireBullet(a.x + px * spawnOffset, a.y + py * spawnOffset, nx * forward - px * inward, ny * forward - py * inward, GameAssets.bossBulletBlue())
        MinionBehaviorShared.fireBullet(a.x - px * spawnOffset, a.y - py * spawnOffset, nx * forward + px * inward, ny * forward + py * inward, GameAssets.bossBulletBlue())
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, dist: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        let a = r.sprite
        if (canTrack) {
            let desired = 55, radial = (dist - desired) * 0.9, side = (r.stateA % 2 == 0 ? 1 : -1) * 42
            MinionBehaviorShared.setVel(a, nx * radial - ny * side, ny * radial + nx * side, 58 * speed)
        } else MinionBehaviorShared.wander(r, 24 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(a, r.elite, r.stateA); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 780 : 1050, waveTier, attackDifficulty)) }
    }
}
namespace MinionWalkerBehavior {
    function fire(a: Sprite, elite: boolean) {
        let player = PlayerSystem.getPlayer(); if (player == null) return
        let lead = elite ? 0.42 : 0.30
        let tx = player.x + player.vx * lead, ty = player.y + player.vy * lead
        let dx = tx - a.x, dy = ty - a.y, d = Math.sqrt(dx * dx + dy * dy); if (d < 1) d = 1
        let speed = elite ? 48 : 42
        MinionBehaviorShared.fireBullet(a.x, a.y, dx / d * speed, dy / d * speed, GameAssets.minionWalkerSlug())
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) MinionBehaviorShared.moveCurvedPursuit(r, nx, ny, (r.elite ? 19 : 13) * speed, (r.elite ? 7 : 5) * speed, 0.17)
        else MinionBehaviorShared.wander(r, 12 * speed)
        if (r.elite && canAttack && now >= r.nextAttackAt) { fire(r.sprite, true); r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(1450, waveTier, attackDifficulty)) }
    }
}
namespace MinionSlimeBehavior {
    export function maxGenerationForDifficulty(difficulty: number): number { return GameConfig.MINION_SLIME_MAX_SPLIT_GENERATION }
    export function splitChildCount(difficulty: number, generation: number, elite: boolean): number {
        let d = Math.max(1, Math.min(30, difficulty))
        let count = GameConfig.MINION_SLIME_SPLIT_CHILD_BASE + Math.idiv(d - 1, GameConfig.MINION_SLIME_SPLIT_CHILD_STAGE_STEP)
        if (elite && generation == 0) count += 1
        let generationCap = GameConfig.MINION_SLIME_SPLIT_CHILD_MAX
        if (generation >= 1) generationCap = 2
        if (count > generationCap) count = generationCap
        if (count < 2) count = 2
        return count
    }
    export function generationSpeedScale(generation: number): number {
        if (generation <= 0) return 1
        if (generation == 1) return GameConfig.MINION_SLIME_GEN1_SPEED_PERCENT / 100
        if (generation == 2) return GameConfig.MINION_SLIME_GEN2_SPEED_PERCENT / 100
        return GameConfig.MINION_SLIME_GEN3_SPEED_PERCENT / 100
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, speedScale: number, difficulty: number, waveTier: number, now: number) {
        let a = r.sprite, generationScale = generationSpeedScale(r.splitGeneration)
        let phase = r.stateB
        if (phase == 10) {
            MinionBehaviorShared.steerVelocity(a, 0, 0, 0.55)
            if (now < r.nextAttackAt) return
            let pounceSpeed = EnemyFramework.scaleStage30(GameConfig.MINION_SLIME_POUNCE_SPEED_STAGE1, GameConfig.MINION_SLIME_POUNCE_SPEED_STAGE30, difficulty)
            pounceSpeed *= r.elite ? 1.12 : 1.0
            pounceSpeed *= 1 + Math.min(6, waveTier) * 0.025
            pounceSpeed *= generationScale
            r.burstVX = nx * pounceSpeed; r.burstVY = ny * pounceSpeed
            r.stateB = 11; r.nextAttackAt = now + GameConfig.MINION_SLIME_POUNCE_DURATION_MS
            SoundSystem.minionSlimePounce(); return
        }
        if (phase == 11) {
            MinionBehaviorShared.steerVelocity(a, r.burstVX, r.burstVY, 0.72)
            if (now >= r.nextAttackAt) {
                r.stateB = 0; r.burstVX = 0; r.burstVY = 0
                let pounceCooldown = randint(GameConfig.MINION_SLIME_POUNCE_COOLDOWN_MIN_MS, GameConfig.MINION_SLIME_POUNCE_COOLDOWN_MAX_MS)
                r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, pounceCooldown)
            }
            return
        }
        MinionBehaviorShared.moveCurvedPursuit(r, nx, ny, 16 * speedScale * generationScale, 5 * speedScale * generationScale, 0.18)
        if (now >= r.nextAttackAt) { r.stateB = 10; r.nextAttackAt = now + GameConfig.MINION_SLIME_POUNCE_PAUSE_MS; MinionBehaviorShared.steerVelocity(a, 0, 0, 0.72) }
    }
}
namespace MinionEyeBehavior {
    function fire(a: Sprite, elite: boolean) {
        let player = PlayerSystem.getPlayer(); if (player == null) return
        let dx = player.x - a.x, dy = player.y - a.y, d = Math.sqrt(dx * dx + dy * dy); if (d < 1) d = 1
        let speed = elite ? 82 : 70
        MinionBehaviorShared.fireBullet(a.x, a.y, dx / d * speed, dy / d * speed, elite ? GameAssets.bossBulletAimedHard() : GameAssets.bossBulletAimed())
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, dist: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) MinionBehaviorShared.keepDistance(r.sprite, nx, ny, dist, 76, 26 * speed)
        else MinionBehaviorShared.wander(r, 14 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite); r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 1000 : 1350, waveTier, attackDifficulty)) }
    }
}
namespace MinionMothBehavior {
    function fire(a: Sprite, elite: boolean, phase: number) {
        let dx = a.vx, dy = a.vy, d = Math.sqrt(dx * dx + dy * dy)
        let base = d >= 1 ? Math.atan2(dy, dx) : (phase * 0.73)
        let count = elite ? 6 : 4, speed = elite ? 48 : 43
        for (let i = 0; i < count; i++) {
            let wingIndex = Math.idiv(i, 2), side = i % 2 == 0 ? -1 : 1
            let deg = elite ? (18 + wingIndex * 21) : (24 + wingIndex * 30)
            let angle = base + side * deg * Math.PI / 180
            MinionBehaviorShared.fireBullet(a.x, a.y, Math.cos(angle) * speed, Math.sin(angle) * speed, GameAssets.bossBulletSweep())
        }
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, dist: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) { let side = (r.stateA % 2 == 0 ? 1 : -1); MinionBehaviorShared.setVel(r.sprite, -ny * 45 * side + nx * (dist - 70) * 0.35, nx * 45 * side + ny * (dist - 70) * 0.35, 52 * speed) }
        else MinionBehaviorShared.wander(r, 22 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite, r.stateA); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 900 : 1250, waveTier, attackDifficulty)) }
    }
}
namespace MinionBeetleBehavior {
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, waveTier: number, attackDifficulty: number, now: number) {
        if (now >= r.nextAttackAt) {
            MinionBehaviorShared.steerVelocity(r.sprite, nx * (r.elite ? 95 : 78), ny * (r.elite ? 95 : 78), 0.34)
            r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 900 : 1250, waveTier, attackDifficulty))
        }
    }
}
namespace MinionJellyBehavior {
    function fire(a: Sprite, elite: boolean, phase: number) {
        let angle = phase * 0.62, speed = elite ? 39 : 34
        MinionBehaviorShared.fireBullet(a.x, a.y, Math.cos(angle) * speed, Math.sin(angle) * speed, GameAssets.bossBulletSpiral())
        if (elite) { let opposite = angle + Math.PI; MinionBehaviorShared.fireBullet(a.x, a.y, Math.cos(opposite) * speed, Math.sin(opposite) * speed, GameAssets.bossBulletSpiralHard()) }
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, speed: number, canAttack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        MinionBehaviorShared.setVel(r.sprite, Math.cos((now + r.stateA * 10) / 700) * 18, Math.sin((now + r.stateA * 10) / 900) * 18, 25 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite, r.stateA); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 1200 : 1600, waveTier, attackDifficulty)) }
    }
}
namespace MinionSpiderBehavior {
    function fire(a: Sprite, elite: boolean) {
        let dl = a.x, dr = GameConfig.WORLD_WIDTH - a.x, dt = a.y, db = GameConfig.WORLD_HEIGHT - a.y
        let nx = 1, ny = 0, nearest = dl
        if (dr < nearest) { nearest = dr; nx = -1; ny = 0 }
        if (dt < nearest) { nearest = dt; nx = 0; ny = 1 }
        if (db < nearest) { nx = 0; ny = -1 }
        let px = -ny, py = nx, count = elite ? 6 : 4, spacing = elite ? 5 : 6, speed = elite ? 48 : 42
        for (let i = 0; i < count; i++) {
            let lateral = (i - (count - 1) / 2) * spacing
            MinionBehaviorShared.fireBullet(a.x + px * lateral, a.y + py * lateral, nx * speed, ny * speed, elite ? GameAssets.bossBulletArcHard() : GameAssets.bossBulletArc())
        }
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, player: Sprite, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) MinionBehaviorShared.moveAlongNearestEdge(r.sprite, player, r.elite ? 36 : 27)
        else MinionBehaviorShared.wander(r, 18 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite); r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 900 : 1250, waveTier, attackDifficulty)) }
    }
}
namespace MinionCrabBehavior {
    function fire(a: Sprite, elite: boolean) {
        let rows = elite ? 2 : 1
        for (let row = 0; row < rows; row++) {
            let yOffset = (row - (rows - 1) / 2) * 10, speed = elite ? 58 : 52
            MinionBehaviorShared.fireBullet(a.x, a.y + yOffset, -speed, 0, GameAssets.bossBulletRed())
            MinionBehaviorShared.fireBullet(a.x, a.y + yOffset, speed, 0, GameAssets.bossBulletRed())
        }
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, player: Sprite, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        let crabY = canTrack ? Math.max(-20, Math.min(20, (player.y - r.sprite.y) * 0.3)) : 0
        MinionBehaviorShared.steerVelocity(r.sprite, (r.stateA % 2 == 0 ? 1 : -1) * (r.elite ? 42 : 31), crabY, 0.20)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 850 : 1200, waveTier, attackDifficulty)) }
    }
}
namespace MinionBomberBehavior {
    function fire(a: Sprite, elite: boolean) {
        let mine = sprites.create(GameAssets.bossMine(), SpriteKind.BossBullet)
        mine.z = GameConfig.BOSS_BULLET_Z; mine.setFlag(SpriteFlag.AutoDestroy, false); mine.setPosition(a.x, a.y); mine.vx = 0; mine.vy = 0; mine.lifespan = elite ? 1800 : 1400
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, dist: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) MinionBehaviorShared.moveCurvedPursuit(r, nx, ny, 20 * speed, (r.elite ? 19 : 15) * speed, 0.15)
        else MinionBehaviorShared.wander(r, 13 * speed)
        if (dist < 46 && canAttack && now >= r.nextAttackAt) {
            fire(r.sprite, r.elite)
            let recoil = r.elite ? 62 : 54
            MinionBehaviorShared.steerVelocity(r.sprite, -nx * recoil, -ny * recoil, 1.0)
            r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(1700, waveTier, attackDifficulty))
        }
    }
}
namespace MinionWispBehavior {
    function fire(a: Sprite, elite: boolean, phase: number) {
        let dx = a.vx, dy = a.vy, d = Math.sqrt(dx * dx + dy * dy)
        if (d < 1) { let angle = (phase % 8) * Math.PI / 4; dx = Math.cos(angle); dy = Math.sin(angle); d = 1 }
        let speed = elite ? 28 : 23
        MinionBehaviorShared.fireBullet(a.x, a.y, dx / d * speed, dy / d * speed, GameAssets.minionWispLargeOrb())
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) { let side = (r.stateA % 2 == 0 ? 1 : -1); MinionBehaviorShared.setVel(r.sprite, nx * 12 - ny * 24 * side, ny * 12 + nx * 24 * side, 32 * speed) }
        else MinionBehaviorShared.wander(r, 17 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite, r.stateA); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 1200 : 1700, waveTier, attackDifficulty)) }
    }
}
namespace MinionMaskBehavior {
    function fire(a: Sprite, elite: boolean, phase: number) {
        let base = phase % 2 == 0 ? Math.PI / 4 : -Math.PI / 4, speed = elite ? 48 : 42
        MinionBehaviorShared.fireBullet(a.x, a.y, Math.cos(base) * speed, Math.sin(base) * speed, GameAssets.bossBulletCross())
        MinionBehaviorShared.fireBullet(a.x, a.y, Math.cos(base + Math.PI) * speed, Math.sin(base + Math.PI) * speed, GameAssets.bossBulletCross())
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, nx: number, ny: number, dist: number, speed: number, canAttack: boolean, canTrack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        if (canTrack) MinionBehaviorShared.keepDistance(r.sprite, nx, ny, dist, 68, 23 * speed)
        else MinionBehaviorShared.wander(r, 14 * speed)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite, r.stateA); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 900 : 1300, waveTier, attackDifficulty)) }
    }
}
namespace MinionFlowerBehavior {
    function fire(a: Sprite, elite: boolean, phase: number) {
        let count = elite ? 10 : 6, speed = elite ? 40 : 36, offset = phase * 0.31
        for (let i = 0; i < count; i++) {
            let angle = offset + i * Math.PI * 2 / count
            MinionBehaviorShared.fireBullet(a.x, a.y, Math.cos(angle) * speed, Math.sin(angle) * speed, elite ? GameAssets.bossBulletPetalHard() : GameAssets.bossBulletPetal())
        }
    }
    export function update(r: MinionRuntimeSystem.MinionRuntime, canAttack: boolean, waveTier: number, attackDifficulty: number, now: number) {
        MinionBehaviorShared.steerVelocity(r.sprite, Math.cos((now + r.stateA * 13) / 900) * 10, Math.sin((now + r.stateA * 17) / 900) * 10, 0.16)
        if (canAttack && now >= r.nextAttackAt) { fire(r.sprite, r.elite, r.stateA); r.stateA += 1; r.nextAttackAt = MinionBehaviorShared.scheduleNextAttack(r, now, MinionBehaviorShared.scaledAttackCooldown(r.elite ? 1150 : 1550, waveTier, attackDifficulty)) }
    }
}
namespace MinionMedicBehavior {
    export function update(r: MinionRuntimeSystem.MinionRuntime, now: number) {
        let a = r.sprite, best: MinionRuntimeSystem.MinionRuntime = null, bestD = 999999
        for (let i = 0; i < MinionRuntimeSystem.count(); i++) {
            let other = MinionRuntimeSystem.get(i)
            if (other == null || other == r || other.sprite == null || other.hp <= 0 || other.hp >= other.maxHP) continue
            let dx = other.sprite.x - a.x, dy = other.sprite.y - a.y, d = dx * dx + dy * dy
            if (d < bestD) { bestD = d; best = other }
        }
        if (best == null) { a.vx = 0; a.vy = 0; return }
        let target = best.sprite, dx = target.x - a.x, dy = target.y - a.y, d = Math.sqrt(dx * dx + dy * dy); if (d < 1) d = 1
        if (d > 28) MinionBehaviorShared.steerVelocity(a, dx / d * (r.elite ? 34 : 26), dy / d * (r.elite ? 34 : 26), 0.18)
        else {
            MinionBehaviorShared.steerVelocity(a, 0, 0, 0.22)
            if (now >= r.nextAttackAt) {
                best.hp = Math.min(best.maxHP, best.hp + (r.elite ? 2 : 1)); target.startEffect(effects.ashes, 80)
                let healCooldown = r.elite ? 700 : 1000
                if (r.hardSummoned) healCooldown = Math.idiv(healCooldown * GameConfig.SUMMONER_HARD_ATTACK_INTERVAL_PERCENT, 100)
                r.nextAttackAt = now + healCooldown
            }
        }
    }
}
namespace MinionBehaviorSystem {
    export function update(r: MinionRuntimeSystem.MinionRuntime, player: Sprite, now: number) {
        if (r == null || r.sprite == null || r.hp <= 0 || player == null) return
        let a = r.sprite
        let dx = player.x - a.x, dy = player.y - a.y, dist = Math.sqrt(dx * dx + dy * dy); if (dist < 1) dist = 1
        let nx = dx / dist, ny = dy / dist
        let waveTier = r.spawnWaveTier; if (waveTier < 0) waveTier = 0
        let difficultyLevel = r.difficultyLevel; if (difficultyLevel < 1) difficultyLevel = 1
        let attackDifficulty = r.summoned ? difficultyLevel : StageSystem.getLevel()
        let moveBoost = 1 + Math.min(6, waveTier) * 0.06
        let stageMovePercent = EnemyFramework.scaleStage30(GameConfig.MINION_STAGE_MOVE_PERCENT_START, GameConfig.MINION_STAGE_MOVE_PERCENT_END, difficultyLevel)
        let speed = (r.elite ? 1.16 : 1.0) * moveBoost * stageMovePercent / 100
        let canAttack = !MinionCatalog.requiresPlayerAttackRange(r.type) || dist <= MinionCatalog.visionRange(r.type, r.elite)
        let canTrack = !MinionCatalog.requiresPlayerMovementRange(r.type, r.elite) || dist <= MinionCatalog.visionRange(r.type, r.elite)
        MinionBehaviorShared.nudgeBackFromWorldEdge(a, Math.max(20, 34 * speed))
        if (MinionBehaviorShared.updateHitResponse(r, speed)) return
        if (r.type == MinionCatalog.GHOST) MinionGhostBehavior.update(r, nx, ny, speed)
        else if (r.type == MinionCatalog.BAT) MinionBatBehavior.update(r, nx, ny, dist, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.WALKER) MinionWalkerBehavior.update(r, nx, ny, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.SLIME) MinionSlimeBehavior.update(r, nx, ny, speed, difficultyLevel, waveTier, now)
        else if (r.type == MinionCatalog.EYE) MinionEyeBehavior.update(r, nx, ny, dist, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.MOTH) MinionMothBehavior.update(r, nx, ny, dist, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.BEETLE) MinionBeetleBehavior.update(r, nx, ny, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.JELLY) MinionJellyBehavior.update(r, speed, canAttack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.SPIDER) MinionSpiderBehavior.update(r, player, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.CRAB) MinionCrabBehavior.update(r, player, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.BOMBER) MinionBomberBehavior.update(r, nx, ny, dist, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.WISP) MinionWispBehavior.update(r, nx, ny, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.MASK) MinionMaskBehavior.update(r, nx, ny, dist, speed, canAttack, canTrack, waveTier, attackDifficulty, now)
        else if (r.type == MinionCatalog.FLOWER) MinionFlowerBehavior.update(r, canAttack, waveTier, attackDifficulty, now)
        else MinionMedicBehavior.update(r, now)
    }
}
