    let gameEntryPrepared = false
    export function init() {
        if (initialized) return
        initialized = true
        MinionIndicatorSystem.init()
        warningHud = sprites.create(image.create(160, 120), SpriteKind.Hud)
        warningHud.setFlag(SpriteFlag.RelativeToCamera, true)
        warningHud.setFlag(SpriteFlag.Ghost, true)
        warningHud.setFlag(SpriteFlag.Invisible, true)
        warningHud.z = GameConfig.HUD_Z + 40
        warningHud.setPosition(80, 60)
        stageIntroHud = sprites.create(image.create(160, 120), SpriteKind.Hud)
        stageIntroHud.setFlag(SpriteFlag.RelativeToCamera, true)
        stageIntroHud.setFlag(SpriteFlag.Ghost, true)
        stageIntroHud.setFlag(SpriteFlag.Invisible, true)
        stageIntroHud.z = GameConfig.HUD_Z + 20
        stageIntroHud.setPosition(80, 60)
        waveNoticeHud = sprites.create(image.create(96, 13), SpriteKind.Hud)
        waveNoticeHud.setFlag(SpriteFlag.RelativeToCamera, true)
        waveNoticeHud.setFlag(SpriteFlag.Ghost, true)
        waveNoticeHud.setFlag(SpriteFlag.Invisible, true)
        waveNoticeHud.z = GameConfig.HUD_Z + 25
        waveNoticeHud.setPosition(80, 17)
        GameUpdateScheduler.every(GameConfig.MINION_UPDATE_INTERVAL_MS, function () { update() })
        GameUpdateScheduler.every(GameConfig.MINION_OUT_OF_WORLD_DAMAGE_INTERVAL_MS, function () { damageOutOfWorldMinions() })
    }
    export function startStage() {
        clearAllMinions(false)
        if (GameSession.isBossOnlyMode()) {
            stageActive = false; stageIntroActive = false; preWarningActive = false; warningActive = false
            if (warningHud != null) warningHud.setFlag(SpriteFlag.Invisible, true)
            if (waveNoticeHud != null) waveNoticeHud.setFlag(SpriteFlag.Invisible, true)
            if (stageIntroHud != null) stageIntroHud.setFlag(SpriteFlag.Invisible, true)
            BossSystem.prepareStagePlan()
            PlayerSystem.resetStageDamageCount()
            ScoreSystem.startStage()
            GrazeSystem.startStage()
            ShieldSystem.resetForStage()
            WorldSystem.randomizeBackgroundForStage()
            beginBossWarning()
            return
        }
        if (!gameEntryPrepared) MusicSystem.playMinionBgm()
        BossSystem.prepareStagePlan()
        selectedTypes = chooseStageTypes()
        stageActive = true; stageIntroActive = true; preWarningActive = false; warningActive = false; warningUntil = 0; warningStartedAt = 0; preWarningUntil = 0; waveIndex = 0; nextWaveReadyAt = 0; currentWaveOriginalCount = 0
        stageTargetCount = getTargetCountForStage(StageSystem.getLevel())
        stageSpawnedCount = 0; stageDefeatedCount = 0; stageStartedAt = 0
        buildStageSpawnPlan()
        waveNoticeUntil = 0
        stageIntroStartedAt = game.runtime()
        stageIntroUntil = stageIntroStartedAt + GameConfig.STAGE_INTRO_MS
        if (warningHud != null) warningHud.setFlag(SpriteFlag.Invisible, true)
        if (waveNoticeHud != null) waveNoticeHud.setFlag(SpriteFlag.Invisible, true)
        if (stageIntroHud != null) { stageIntroHud.setFlag(SpriteFlag.Invisible, false); renderStageIntro(stageIntroStartedAt) }
        PlayerSystem.resetStageDamageCount()
        ScoreSystem.startStage()
        GrazeSystem.startStage()
        ShieldSystem.resetForStage()
        WorldSystem.randomizeBackgroundForStage()
        if (!gameEntryPrepared) SoundSystem.stageIntro()
    }
    export function startStageForGameEntry() {
        gameEntryPrepared = true
        startStage()
    }
    export function updateGameEntryPresentation() {
        let now = game.runtime()
        if (stageIntroActive) renderStageIntro(now)
        if (warningActive) renderBossWarning(now)
    }
    export function finishGameEntryPresentation() {
        let now = game.runtime()
        if (stageIntroActive) {
            renderStageIntro(now)
            if (now >= stageIntroUntil) {
                stageIntroActive = false
                if (stageIntroHud != null) stageIntroHud.setFlag(SpriteFlag.Invisible, true)
                stageStartedAt = now
                spawnNextWave()
            }
        }
        if (warningActive) {
            renderBossWarning(now)
            if (now >= warningUntil) {
                warningActive = false
                stageActive = false
                if (warningHud != null) warningHud.setFlag(SpriteFlag.Invisible, true)
                BossSystem.startBossPhase()
            }
        }
        if (!GameSession.isBossOnlyMode()) MusicSystem.playMinionBgm()
        gameEntryPrepared = false
    }
    export function isStageActive(): boolean { return stageActive }
    export function isTransitionActive(): boolean { return stageIntroActive || preWarningActive || warningActive }
    export function getStageTimeLimitMs(): number {
        let limit = GameConfig.MINION_TIME_BASE_MS + stageTargetCount * GameConfig.MINION_TIME_PER_TARGET_MS
        if (limit > GameConfig.MINION_TIME_MAX_MS) limit = GameConfig.MINION_TIME_MAX_MS
        return limit
    }
    export function getStageElapsedMs(): number {
        if (stageStartedAt <= 0) return 0
        return game.runtime() - stageStartedAt
    }
    export function getStageCountdownMs(): number {
        if (!stageActive) return 0
        let remaining = getStageTimeLimitMs() - getStageElapsedMs()
        return remaining > 0 ? remaining : 0
    }
    export function isEliteEnemy(enemy: Sprite): boolean { let r = MinionRuntimeSystem.get(MinionRuntimeSystem.indexOfSprite(enemy)); return r != null && r.elite }
    export function getCombinedHP(): number { return Math.max(0, stageTargetCount - stageDefeatedCount) }
    export function getCombinedMaxHP(): number { return Math.max(1, stageTargetCount) }
    function chooseStageTypes(): number[] {
        let wanted = randint(GameConfig.MINION_STAGE_MIN_TYPES, GameConfig.MINION_STAGE_MAX_TYPES)
        let result: number[] = []
        let bossCount = BossSystem.getPlannedBossCount()
        for (let i = 0; i < bossCount; i++) {
            let affinity = getAffinityForBoss(BossSystem.getPlannedBossType(i))
            pushUnique(result, affinity)
        }
        while (result.length < wanted) {
            let pick = weightedMinionPick(result)
            if (pick < 0) break
            pushUnique(result, pick)
        }
        return result
    }
    function getAffinityForBoss(type: number): number { return MinionCatalog.affinityForBoss(type) }
    function weightedMinionPick(excluded: number[]): number {
        let weighted: number[] = []
        for (let t = 0; t < GameConfig.MINION_TYPE_COUNT; t++) {
            if (indexOfNumber(excluded, t) >= 0) continue
            let w = 2
            for (let b = 0; b < BossSystem.getPlannedBossCount(); b++) {
                let bt = BossSystem.getPlannedBossType(b)
                if (getAffinityForBoss(bt) == t) w += 7
                if (bt == 1 && (t == SPIDER || t == CRAB)) w += 3
                if (bt == 2 && (t == EYE || t == WALKER)) w += 3
                if (bt == 3 && (t == FLOWER || t == MOTH || t == JELLY)) w += 3
                if (bt == 4 && (t == GHOST || t == BEETLE || t == BOMBER)) w += 3
                if (bt == 5 && (t == SLIME || t == MEDIC || t == WISP)) w += 3
            }
            for (let n = 0; n < w; n++)weighted.push(t)
        }
        if (weighted.length <= 0) return -1
        return weighted[randint(0, weighted.length - 1)]
    }
    function pushUnique(arr: number[], v: number) { if (indexOfNumber(arr, v) < 0) arr.push(v) }
    function indexOfNumber(arr: number[], v: number): number { for (let i = 0; i < arr.length; i++)if (arr[i] == v) return i; return -1 }
    function getTargetCountForStage(stage: number): number {
        if (stage < 1) stage = 1
        return GameConfig.MINION_TARGET_BASE_COUNT + Math.idiv((stage - 1) * GameConfig.MINION_TARGET_GROWTH_NUMERATOR, GameConfig.MINION_TARGET_GROWTH_DENOMINATOR)
    }
    function buildStageSpawnPlan() {
        stagePlanTypes = []; stagePlanElites = []
        let stage = StageSystem.getLevel()
        for (let i = 0; i < stageTargetCount; i++) {
            let type = selectedTypes[randint(0, selectedTypes.length - 1)]
            let elite = rollElite(stage)
            stagePlanTypes.push(type); stagePlanElites.push(elite)
        }
        HudSystem.updateBossHP()
    }
    function getWaveSizeForIndex(index: number): number {
        let stage = StageSystem.getLevel()
        if (stage < 1) stage = 1
        let count = GameConfig.MINION_WAVE_BASE_COUNT + Math.idiv(stage - 1, GameConfig.MINION_WAVE_STAGES_PER_EXTRA)
        if (count > GameConfig.MINION_WAVE_MAX_COUNT) count = GameConfig.MINION_WAVE_MAX_COUNT
        return count
    }
    function spawnNextWave() {
        if (!stageActive || warningActive || stageSpawnedCount >= stageTargetCount) return
        let remaining = stageTargetCount - stageSpawnedCount
        let count = getWaveSizeForIndex(waveIndex)
        if (count > remaining) count = remaining
        let tail = remaining - count
        if (tail > 0 && tail <= 2 && count + tail <= GameConfig.MINION_WAVE_MAX_COUNT) count += tail
        showWaveNotice(waveIndex + 1)
        SoundSystem.minionWaveIncoming()
        for (let i = 0; i < count; i++) {
            let planIndex = stageSpawnedCount + i
            let type = stagePlanTypes[planIndex]
            let elite = stagePlanElites[planIndex]
            spawn(type, elite, null, false, true, 0, waveIndex, StageSystem.getLevel(), false)
        }
        stageSpawnedCount += count
        currentWaveOriginalCount = count
        waveIndex += 1
        nextWaveReadyAt = game.runtime() + count * GameConfig.MINION_WAVE_TIMER_PER_SLOT_MS
    }
    function rollElite(stage: number): boolean {
        if (stage < 1) stage = 1
        let chance = 5
        if (stage <= 10) chance = 5 + Math.idiv((stage - 1) * 20, 9)
        else chance = 25 + Math.idiv(stage - 10, 2)
        if (chance > GameConfig.MINION_ELITE_CHANCE_CAP_PERCENT) chance = GameConfig.MINION_ELITE_CHANCE_CAP_PERCENT
        return randint(1, 100) <= chance
    }
    let slimeGenerationImageCache: Image[] = []
    function slimeGenerationImage(elite: boolean, generation: number, damageLevel: number): Image {
        if (generation < 0) generation = 0
        if (generation > GameConfig.MINION_SLIME_MAX_SPLIT_GENERATION) generation = GameConfig.MINION_SLIME_MAX_SPLIT_GENERATION
        if (damageLevel < 0) damageLevel = 0; if (damageLevel > 3) damageLevel = 3
        let generationCount = GameConfig.MINION_SLIME_MAX_SPLIT_GENERATION + 1
        let cacheIndex = ((elite ? 1 : 0) * generationCount + generation) * 4 + damageLevel
        if (slimeGenerationImageCache[cacheIndex] != null) return slimeGenerationImageCache[cacheIndex]
        let size = elite ? 15 : 11
        if (generation == 1) size -= 2
        else if (generation == 2) size -= 4
        else if (generation == 3) size -= 5
        else if (generation >= 4) size -= 6
        if (size < 7) size = 7
        let out = image.create(size, size)
        let mid = Math.idiv(size, 2)
        let r = Math.max(2, mid - 1)
        let color = generation == 0 ? 11 : (generation == 1 ? 7 : (generation == 2 ? 8 : (generation == 3 ? 6 : 5)))
        if (elite) color = generation == 0 ? 2 : (generation == 1 ? 4 : (generation == 2 ? 10 : (generation == 3 ? 9 : 5)))
        for (let y = mid - r + 1; y <= mid + r; y++) for (let x = mid - r; x <= mid + r; x++) {
            let dx = x - mid, dy = y - (mid + 1)
            if (dx * dx * 2 + dy * dy <= r * r * 2 + 2) out.setPixel(x, y, color)
        }
        out.setPixel(mid - 1, mid, 1); out.setPixel(mid + 1, mid, 1)
        if (mid - 2 >= 0 && mid - 1 >= 0) out.setPixel(mid - 2, mid - 1, 1)
        for (let x = Math.max(0, mid - r + 1); x <= Math.min(size - 1, mid + r - 1); x++)if ((x + generation) % 3 == 0) out.setPixel(x, Math.min(size - 1, mid + r), 15)
        if (elite) { out.setPixel(1, 1, 5); out.setPixel(size - 2, 1, 5) }
        if (damageLevel > 0) {
            for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
                if (out.getPixel(x, y) == 0) continue
                let edge = Math.min(Math.min(x, size - 1 - x), Math.min(y, size - 1 - y))
                if (damageLevel >= 1 && edge == 0 && (x + y) % 3 == 0) out.setPixel(x, y, 0)
                if (damageLevel >= 2 && edge <= 1 && (x * 2 + y) % 4 == 0) out.setPixel(x, y, 0)
                if (damageLevel >= 3 && edge <= 2 && (x + y * 2) % 4 == 1) out.setPixel(x, y, 0)
            }
        }
        slimeGenerationImageCache[cacheIndex] = out
        return out
    }
    function minionSpawnImage(type: number, elite: boolean, generation: number): Image {
        if (type == SLIME) return slimeGenerationImage(elite, generation, 0)
        return GameAssets.minionImage(type, elite)
    }
    function registerMinionActorAt(type: number, elite: boolean, owner: Sprite, isSummoned: boolean, countsForTarget: boolean, splitGeneration: number, waveTier: number, difficultyStage: number, isBossSupport: boolean, x: number, y: number, readyAt: number, hiddenDuringTelegraph: boolean, isHardSummon?: boolean): Sprite {
        let actorImage = minionSpawnImage(type, elite, splitGeneration).clone()
        let actor = EnemyFramework.createWorldActor(actorImage, SpriteKind.Minion, x, y, GameConfig.BOSS_Z - 5)
        let minX = MinionBehaviorShared.minX(actor), maxX = MinionBehaviorShared.maxX(actor), minY = MinionBehaviorShared.minY(actor), maxY = MinionBehaviorShared.maxY(actor)
        actor.setPosition(clamp(x, minX, maxX), clamp(y, minY, maxY))
        let weakenedSummon = isSummoned && owner != null && BossSystem.isDualBossStage()
        let hp = calculateMinionHP(type, elite, weakenedSummon, waveTier, difficultyStage)
        if (isHardSummon == true) hp = Math.max(1, Math.idiv(hp * GameConfig.SUMMONER_HARD_HP_PERCENT + 99, 100))
        if (type == SLIME && splitGeneration > 0) {
            let divisor = 1
            for (let g = 0; g < splitGeneration; g++)divisor *= 2
            hp = Math.max(1, Math.idiv(hp, divisor))
        }
        let runtime = new MinionRuntimeSystem.MinionRuntime(actor, type, elite, hp, owner, isSummoned, countsForTarget, splitGeneration, waveTier, difficultyStage, isBossSupport, readyAt, hiddenDuringTelegraph, isHardSummon == true)
        let index = MinionRuntimeSystem.add(runtime)
        if (hiddenDuringTelegraph) {
            actor.setFlag(SpriteFlag.Invisible, true); actor.setFlag(SpriteFlag.Ghost, true)
            createMinionSpawnEffect(actor, elite, runtime.spawnReadyAt)
        } else {
            actor.setFlag(SpriteFlag.Invisible, false); actor.setFlag(SpriteFlag.Ghost, false)
            SoundSystem.minionMaterialize()
        }
        updateMinionHealthBar(index)
        return actor
    }
    function spawn(type: number, elite: boolean, owner: Sprite, isSummoned: boolean, countsForTarget: boolean, splitGeneration: number, waveTier: number, difficultyStage: number, isBossSupport: boolean): Sprite {
        if (owner == null) {
            scheduleWorldSpawn(type, elite, countsForTarget, splitGeneration, waveTier, difficultyStage, isBossSupport)
            return null
        }
        let preview = minionSpawnImage(type, elite, splitGeneration)
        let halfW = Math.idiv(preview.width + 1, 2), halfH = Math.idiv(preview.height + 1, 2)
        let minX = halfW + GameConfig.MINION_WORLD_ROUTE_MARGIN, maxX = GameConfig.WORLD_WIDTH - halfW - GameConfig.MINION_WORLD_ROUTE_MARGIN
        let minY = halfH + GameConfig.MINION_WORLD_ROUTE_MARGIN, maxY = GameConfig.WORLD_HEIGHT - halfH - GameConfig.MINION_WORLD_ROUTE_MARGIN
        let x = owner.x, y = owner.y
        if (isSummoned) { let a = randint(0, 359) * Math.PI / 180, r = randint(36, 66); x = owner.x + Math.cos(a) * r; y = owner.y + Math.sin(a) * r }
        else { x = owner.x + randint(-14, 14); y = owner.y + randint(-14, 14) }
        x = clamp(x, minX, maxX); y = clamp(y, minY, maxY)
        let born = game.runtime(), telegraphMs = splitGeneration > 0 ? 500 : 1400
        return registerMinionActorAt(type, elite, owner, isSummoned, countsForTarget, splitGeneration, waveTier, difficultyStage, isBossSupport, x, y, born + telegraphMs, true)
    }
    function chooseRandomWorldSpawnPoint(spawnImage: Image): number[] {
        let halfW = Math.idiv(spawnImage.width + 1, 2)
        let halfH = Math.idiv(spawnImage.height + 1, 2)
        let minX = halfW + GameConfig.MINION_WORLD_ROUTE_MARGIN
        let maxX = GameConfig.WORLD_WIDTH - halfW - GameConfig.MINION_WORLD_ROUTE_MARGIN
        let minY = halfH + GameConfig.MINION_WORLD_ROUTE_MARGIN
        let maxY = GameConfig.WORLD_HEIGHT - halfH - GameConfig.MINION_WORLD_ROUTE_MARGIN
        let player = PlayerSystem.getPlayer()
        let x = randint(minX, maxX), y = randint(minY, maxY)
        if (player == null) return [x, y]
        let minDistance = GameConfig.MINION_PLAYER_SPAWN_MIN_DISTANCE
        let minDistanceSquared = minDistance * minDistance
        let dx = x - player.x, dy = y - player.y
        while (dx * dx + dy * dy < minDistanceSquared) {
            x = randint(minX, maxX)
            y = randint(minY, maxY)
            dx = x - player.x
            dy = y - player.y
        }
        return [x, y]
    }
    function scheduleWorldSpawn(type: number, elite: boolean, countsForTarget: boolean, splitGeneration: number, waveTier: number, difficultyStage: number, isBossSupport: boolean) {
        let spawnImage = minionSpawnImage(type, elite, splitGeneration)
        let point = chooseRandomWorldSpawnPoint(spawnImage)
        let born = game.runtime()
        let telegraphMs = 0
        if (countsForTarget) {
            let baseTelegraphMs = randint(GameConfig.MINION_SPAWN_TELEGRAPH_MS, GameConfig.MINION_SPAWN_TELEGRAPH_MAX_MS)
            let percent = waveTier <= 0 ? GameConfig.MINION_FIRST_WAVE_SPAWN_PERCENT : GameConfig.MINION_LATER_WAVE_SPAWN_PERCENT
            telegraphMs = Math.idiv(baseTelegraphMs * percent, 100)
        } else {
            telegraphMs = 1400
        }
        let readyAt = born + telegraphMs
        pendingWorldTypes.push(type)
        pendingWorldElites.push(elite)
        pendingWorldCountsTowardStageTarget.push(countsForTarget)
        pendingWorldSplitGenerations.push(splitGeneration)
        pendingWorldWaveTiers.push(waveTier)
        pendingWorldDifficultyLevels.push(Math.max(1, difficultyStage))
        pendingWorldBossSupport.push(isBossSupport)
        pendingWorldX.push(point[0])
        pendingWorldY.push(point[1])
        pendingWorldReadyAts.push(readyAt)
        createMinionSpawnEffectAt(point[0], point[1], elite, readyAt)
    }
    function updatePendingWorldSpawns() {
        let now = game.runtime()
        for (let i = pendingWorldTypes.length - 1; i >= 0; i--) {
            if (now < pendingWorldReadyAts[i]) continue
            let type = pendingWorldTypes[i]
            let elite = pendingWorldElites[i]
            let splitGeneration = pendingWorldSplitGenerations[i]
            let waveTier = pendingWorldWaveTiers[i]
            let difficultyStage = pendingWorldDifficultyLevels[i]
            let isBossSupport = pendingWorldBossSupport[i]
            let countsForTarget = pendingWorldCountsTowardStageTarget[i]
            let x = pendingWorldX[i], y = pendingWorldY[i]
            registerMinionActorAt(type, elite, null, false, countsForTarget, splitGeneration, waveTier, difficultyStage, isBossSupport, x, y, now, false)
            pendingWorldTypes.removeAt(i)
            pendingWorldElites.removeAt(i)
            pendingWorldCountsTowardStageTarget.removeAt(i)
            pendingWorldSplitGenerations.removeAt(i)
            pendingWorldWaveTiers.removeAt(i)
            pendingWorldDifficultyLevels.removeAt(i)
            pendingWorldBossSupport.removeAt(i)
            pendingWorldX.removeAt(i)
            pendingWorldY.removeAt(i)
            pendingWorldReadyAts.removeAt(i)
        }
    }
    function clearPendingWorldSpawns() {
        pendingWorldTypes = []
        pendingWorldElites = []
        pendingWorldCountsTowardStageTarget = []
        pendingWorldSplitGenerations = []
        pendingWorldWaveTiers = []
        pendingWorldDifficultyLevels = []
        pendingWorldBossSupport = []
        pendingWorldX = []
        pendingWorldY = []
        pendingWorldReadyAts = []
        for (let i = spawnEffects.length - 1; i >= 0; i--) {
            if (spawnEffectOwners[i] != null) continue
            if (spawnEffects[i] != null) spawnEffects[i].destroy()
            spawnEffects.removeAt(i); spawnEffectOwners.removeAt(i); spawnEffectBorn.removeAt(i); spawnEffectEnds.removeAt(i); spawnEffectElite.removeAt(i); spawnEffectX.removeAt(i); spawnEffectY.removeAt(i)
        }
    }
    function update() {
        updateShockwaves()
        updateMinionSpawnEffects()
        updateSummonerMarkers()
        if (waveNoticeHud != null && waveNoticeUntil > 0 && game.runtime() >= waveNoticeUntil) { waveNoticeHud.setFlag(SpriteFlag.Invisible, true); waveNoticeUntil = 0 }
        if (!GameSession.isRunning()) return
        updatePendingWorldSpawns()
        let now = game.runtime()
        if (stageIntroActive) {
            renderStageIntro(now)
            if (now >= stageIntroUntil) {
                stageIntroActive = false
                if (stageIntroHud != null) stageIntroHud.setFlag(SpriteFlag.Invisible, true)
                stageStartedAt = now
                spawnNextWave()
            }
            return
        }
        if (preWarningActive) {
            if (now >= preWarningUntil) { preWarningActive = false; beginBossWarning() }
            return
        }
        if (warningActive) {
            renderBossWarning(now)
            SoundSystem.bossApproachWarningPulse()
            if (now >= warningUntil) {
                warningActive = false
                stageActive = false
                if (warningHud != null) warningHud.setFlag(SpriteFlag.Invisible, true)
                BossSystem.startBossPhase()
            }
            return
        }
        if (!stageActive) { updateSummonedOnly(); return }
        updateActors(true)
        let aliveStage = countStageMinions()
        if (stageSpawnedCount >= stageTargetCount) {
            if (aliveStage == 0) finishMinionPhase()
        } else {
            if (nextWaveReadyAt <= 0 || now >= nextWaveReadyAt) {
                let allowedAlive = Math.idiv(currentWaveOriginalCount * 30, 100)
                if (allowedAlive < 0) allowedAlive = 0
                if (aliveStage <= allowedAlive) spawnNextWave()
            }
        }
    }
    function updateSummonedOnly() { updateActors(false) }
    function tutorialActorSlot(actor: Sprite): number {
        for (let i = 0; i < tutorialActors.length; i++)if (tutorialActors[i] == actor) return i
        return -1
    }
    function updateActors(includeStage: boolean) {
        let now = game.runtime(), player = PlayerSystem.getPlayer()
        if (player == null) return
        for (let i = 0; i < MinionRuntimeSystem.count(); i++) {
            let r = MinionRuntimeSystem.get(i)
            if (r == null || r.sprite == null || r.hp <= 0) continue
            if (!includeStage && !r.summoned && !r.bossSupport) continue
            let a = r.sprite, spawnAge = now - r.bornAt
            if (now < r.spawnReadyAt) {
                a.vx = 0; a.vy = 0; a.setFlag(SpriteFlag.Invisible, true)
                if (r.healthBar != null) r.healthBar.setFlag(SpriteFlag.Invisible, true)
                continue
            }
            if (r.stateB < 0) { r.stateB = 0; a.setFlag(SpriteFlag.Invisible, false); a.setFlag(SpriteFlag.Ghost, false); SoundSystem.minionMaterialize() }
            updateMinionHealthBar(i)
            updateMinionAnimation(i, now)
            if (r.elite) updateEliteTrail(i, now)
            let dx = player.x - a.x, dy = player.y - a.y, dist = Math.sqrt(dx * dx + dy * dy); if (dist < 1) dist = 1
            let canAttack = !MinionCatalog.requiresPlayerAttackRange(r.type) || dist <= MinionCatalog.visionRange(r.type, r.elite)
            let tutorialSlot = GameSession.isTutorialMode() ? tutorialActorSlot(a) : -1
            if (tutorialSlot >= 0) {
                let drift = tutorialActorDriftX[tutorialSlot]; if (isNaN(drift)) drift = 0
                a.setPosition(tutorialActorXs[tutorialSlot] + drift * spawnAge / 1000, tutorialActorYs[tutorialSlot]); a.vx = 0; a.vy = 0
                updateMinionHealthBar(i)
                if (tutorialActorCanAttack[tutorialSlot] && canAttack && now >= r.nextAttackAt) {
                    if (r.type == MASK) { fireTutorialArcFan(a, 7, 10, 42); r.nextAttackAt = now + 760 }
                    else if (r.type == EYE) { fireTutorialAimed(a, 3, 8, 58); r.nextAttackAt = now + 900 }
                    else if (r.type == MOTH) { fireTutorialFan(a, 5, 13, 42); r.nextAttackAt = now + 900 }
                    else { fireTutorialAimed(a, 3, 8, 54); r.nextAttackAt = now + 1000 }
                }
                continue
            }
            MinionBehaviorSystem.update(r, player, now)
        }
    }
    function countStageMinions(): number {
        let n = 0
        for (let i = 0; i < MinionRuntimeSystem.count(); i++) { let r = MinionRuntimeSystem.get(i); if (r != null && r.sprite != null && r.hp > 0 && !r.summoned) n++ }
        for (let i = 0; i < pendingWorldTypes.length; i++)if (pendingWorldCountsTowardStageTarget[i]) n++
        return n
    }
    function getIndex(enemy: Sprite): number { return MinionRuntimeSystem.indexOfSprite(enemy) }
    export function getEnemyType(enemy: Sprite): number { let r = MinionRuntimeSystem.get(getIndex(enemy)); return r != null ? r.type : -1 }
    export function damageEnemy(enemy: Sprite, amount: number) {
        damageEnemyInternal(enemy, amount, false)
    }
    export function damageEnemyByShield(enemy: Sprite, amount: number) {
        damageEnemyInternal(enemy, amount, true)
    }
    function damageEnemyInternal(enemy: Sprite, amount: number, fromShield: boolean) {
        let i = getIndex(enemy), r = MinionRuntimeSystem.get(i); if (r == null || amount <= 0 || r.hp <= 0) return
        let actual = amount; if (actual > r.hp) actual = r.hp
        r.hp = EnemyFramework.applyDamageValue(r.hp, actual)
        updateMinionHealthBar(i); updateMinionDamageVisual(i)
        if (r.hp <= 0) { if (fromShield) SoundSystem.shieldKill(); killIndex(i, true, fromShield) }
        else { if (fromShield) SoundSystem.shieldImpact(); MinionBehaviorShared.triggerHitResponse(r); enemy.startEffect(effects.ashes, 50) }
    }
    export function knockBack(enemy: Sprite) {
        let i = getIndex(enemy), p = PlayerSystem.getPlayer(); if (i < 0 || p == null) return
        let dx = enemy.x - p.x, dy = enemy.y - p.y, d = Math.sqrt(dx * dx + dy * dy); if (d < 1) d = 1
        MinionBehaviorShared.steerVelocity(enemy, dx / d * 70, dy / d * 70, 1.0)
    }
    function killIndex(i: number, normalDeath: boolean, fromShield: boolean) {
        let r = MinionRuntimeSystem.get(i); if (r == null || r.sprite == null) return
        let actor = r.sprite, t = r.type, elite = r.elite, wasSummoned = r.summoned, counted = r.countsTowardStageTarget, summonOwner = r.ownerBoss
        r.hp = 0; r.sprite = null
        if (normalDeath) ScoreSystem.awardMinionKill(t, elite, fromShield, actor.x, actor.y)
        if (counted && stageActive) {
            stageDefeatedCount += 1; HudSystem.updateBossHP()
            if (r.splitGeneration == 0 && nextWaveReadyAt > game.runtime()) {
                nextWaveReadyAt -= GameConfig.MINION_WAVE_KILL_REDUCTION_MS
                if (nextWaveReadyAt < game.runtime()) nextWaveReadyAt = game.runtime()
            }
        }
        if (normalDeath && t == SLIME && !wasSummoned && !fromShield) {
            let generation = r.splitGeneration, maxGeneration = MinionSlimeBehavior.maxGenerationForDifficulty(r.difficultyLevel)
            if (generation < maxGeneration) {
                let children = MinionSlimeBehavior.splitChildCount(r.difficultyLevel, generation, elite)
                for (let c = 0; c < children; c++)spawn(SLIME, false, actor, false, false, generation + 1, r.spawnWaveTier, r.difficultyLevel, r.bossSupport)
            }
        }
        if (r.healthBar != null) { r.healthBar.destroy(); r.healthBar = null }
        if (normalDeath && wasSummoned && summonOwner != null) reduceSummonerCooldown(summonOwner)
        if (normalDeath) SoundSystem.minionDeath(elite)
        MinionRuntimeSystem.removeAtSwap(i)
        actor.destroy(effects.disintegrate, elite ? 280 : 180)
        TargetSystem.reset()
    }
    function finishMinionPhase() {
        if (!stageActive || warningActive) return
        nextWaveReadyAt = 0
        MusicSystem.scheduleMinionBgmStopAfterClear()
        beginBossPreWarning()
    }
    function beginBossPreWarning() {
        if (preWarningActive || warningActive) return
        clearStageMinionsOnly(); stageActive = false
        preWarningActive = true; preWarningUntil = game.runtime() + GameConfig.MINION_BOSS_PRE_WARNING_MS
        if (warningHud != null) warningHud.setFlag(SpriteFlag.Invisible, true)
    }
    function beginBossWarning() {
        if (warningActive) return
        warningActive = true
        warningStartedAt = game.runtime()
        warningUntil = warningStartedAt + GameConfig.MINION_BOSS_WARNING_MS
        renderBossWarning(warningStartedAt)
        warningHud.setFlag(SpriteFlag.Invisible, false)
        SoundSystem.bossApproachWarningPulse()
        scene.cameraShake(2, 120)
    }
    let warningBossSilhouetteCache: Image[] = []
    function warningBossSilhouette(type: number, scale: number): Image {
        if (type < 0) type = 0; if (scale < 1) scale = 1
        let key = type * 4 + scale
        if (warningBossSilhouetteCache[key] != null) return warningBossSilhouetteCache[key]
        let src = GameAssets.bossImageForTypeFrame(type, 0)
        let out = image.create(src.width * scale, src.height * scale)
        for (let y = 0; y < src.height; y++)for (let x = 0; x < src.width; x++)if (src.getPixel(x, y) != 0)
            out.fillRect(x * scale, y * scale, scale, scale, 11)
        warningBossSilhouetteCache[key] = out
        return out
    }
    function drawWarningBossCard(p: Image, type: number, cx: number, top: number, scale: number, nameY: number, useFullName: boolean) {
        let sil = warningBossSilhouette(type, scale)
        p.drawTransparentImage(sil, cx - Math.idiv(sil.width, 2), top)
        let name = useFullName ? BossRegistry.displayName(type) : BossRegistry.shortName(type)
        p.print(name, cx - Math.idiv(name.length * 6, 2), nameY, 1, image.font5)
    }
    function renderBossWarning(now: number) {
        if (warningHud == null) return
        let p = warningHud.image
        if (p == null || p.width != 160 || p.height != 120) { p = image.create(160, 120); warningHud.setImage(p) }
        else p.fill(0)
        let bossCount = BossSystem.getPlannedBossCount(); if (bossCount < 1) bossCount = 1
        let duration = GameConfig.MINION_BOSS_WARNING_MS
        let age = now - warningStartedAt; if (age < 0) age = 0
        let remain = warningUntil - now; if (remain < 0) remain = 0
        let inP = Math.min(1000, Math.idiv(age * 1000, 550))
        let outP = Math.min(1000, Math.idiv(remain * 1000, 550))
        let reveal = Math.min(inP, outP)
        reveal = Math.idiv(reveal * reveal, 1000)
        let halfW = Math.idiv(80 * reveal, 1000)
        let stripeH = Math.max(1, Math.idiv(13 * reveal, 1000))
        let left = 80 - halfW, right = 79 + halfW
        let top0 = 10 - Math.idiv(stripeH, 2), bottom0 = 109 - Math.idiv(stripeH, 2)
        let stripeWidth = 6, offset = Math.idiv(now, 42) % (stripeWidth * 2)
        for (let y = top0; y < top0 + stripeH; y++)for (let x = left; x <= right; x++) {
            let band = Math.idiv(x + y - offset + 640, stripeWidth) % 2
            p.setPixel(x, y, band == 0 ? 5 : 15)
        }
        for (let y = bottom0; y < bottom0 + stripeH; y++)for (let x = left; x <= right; x++) {
            let band = Math.idiv(x + y + offset + 640, stripeWidth) % 2
            p.setPixel(x, y, band == 0 ? 5 : 15)
        }
        p.drawLine(left, top0 - 2, right, top0 - 2, 2); p.drawLine(left, top0 - 1, right, top0 - 1, 4)
        p.drawLine(left, top0 + stripeH, right, top0 + stripeH, 4); p.drawLine(left, top0 + stripeH + 1, right, top0 + stripeH + 1, 2)
        p.drawLine(left, bottom0 - 2, right, bottom0 - 2, 2); p.drawLine(left, bottom0 - 1, right, bottom0 - 1, 4)
        p.drawLine(left, bottom0 + stripeH, right, bottom0 + stripeH, 4); p.drawLine(left, bottom0 + stripeH + 1, right, bottom0 + stripeH + 1, 2)
        if (reveal >= 300) {
            if (bossCount == 1) {
                p.print('WARNING', Math.idiv(160 - 7 * 6, 2), 39, 5, image.font5)
                drawWarningBossCard(p, BossSystem.getPlannedBossType(0), 80, 49, 1, 68, true)
                let line = 'BOSS APPROACHING'; p.print(line, Math.idiv(160 - line.length * 6, 2), 82, 4, image.font5)
            } else if (bossCount == 2) {
                let line = 'DUAL BOSS'; p.print(line, Math.idiv(160 - line.length * 6, 2), 39, 5, image.font5)
                drawWarningBossCard(p, BossSystem.getPlannedBossType(0), 40, 49, 1, 68, true)
                drawWarningBossCard(p, BossSystem.getPlannedBossType(1), 120, 49, 1, 68, true)
                line = 'DOUBLE THREAT'; p.print(line, Math.idiv(160 - line.length * 6, 2), 82, 4, image.font5)
            } else if (bossCount == 3) {
                let line = 'TRIPLE BOSS'; p.print(line, Math.idiv(160 - line.length * 6, 2), 37, 5, image.font5)
                drawWarningBossCard(p, BossSystem.getPlannedBossType(0), 28, 49, 1, 68, false)
                drawWarningBossCard(p, BossSystem.getPlannedBossType(1), 80, 49, 1, 68, false)
                drawWarningBossCard(p, BossSystem.getPlannedBossType(2), 132, 49, 1, 68, false)
                line = 'TRIPLE THREAT'; p.print(line, Math.idiv(160 - line.length * 6, 2), 82, 4, image.font5)
            } else {
                let line = '' + bossCount + ' BOSSES'; p.print(line, Math.idiv(160 - line.length * 6, 2), 25, 5, image.font5)
                let topCount = bossCount == 4 ? 2 : 3
                for (let i = 0; i < topCount; i++) {
                    let cx = topCount == 2 ? (52 + i * 56) : (28 + i * 52)
                    drawWarningBossCard(p, BossSystem.getPlannedBossType(i), cx, 34, 1, 51, false)
                }
                let bottomCount = bossCount - topCount
                for (let j = 0; j < bottomCount; j++) {
                    let cx = bottomCount == 2 ? (52 + j * 56) : 80
                    drawWarningBossCard(p, BossSystem.getPlannedBossType(topCount + j), cx, 65, 1, 82, false)
                }
            }
        }
    }
    function renderStageIntro(now: number) {
        if (stageIntroHud == null) return
        let p = stageIntroHud.image
        if (p == null || p.width != 160 || p.height != 120) { p = image.create(160, 120); stageIntroHud.setImage(p) }
        else p.fill(0)
        let elapsed = now - stageIntroStartedAt
        if (elapsed < 0) elapsed = 0
        let duration = GameConfig.STAGE_INTRO_MS
        let progress = Math.idiv(Math.min(elapsed, duration) * 1000, duration)
        let half = Math.idiv(70 * progress, 1000)
        p.drawLine(80 - half, 48, 80 - 8, 48, 12)
        p.drawLine(88, 48, 80 + half, 48, 12)
        p.drawLine(80 - half, 70, 80 - 8, 70, 12)
        p.drawLine(88, 70, 80 + half, 70, 12)
        let label = 'STAGE ' + StageSystem.getLevel()
        p.print(label, 80 - Math.idiv(label.length * 5, 2), 57, 1, image.font5)
    }
