        let img = image.create(96, 13)
        let label = 'WAVE ' + number
        let x = Math.max(1, Math.idiv(96 - label.length * 6, 2))
        img.drawLine(3, 6, 13, 6, 13); img.drawLine(82, 6, 92, 6, 13)
