        let halfW = Math.idiv(rt.sprite.width + 1, 2), halfH = Math.idiv(rt.sprite.height + 1, 2)
        let minX = GameConfig.BOSS_WORLD_EDGE_MARGIN + halfW + 8
        let maxX = GameConfig.WORLD_WIDTH - GameConfig.BOSS_WORLD_EDGE_MARGIN - halfW - 8
        let minY = GameConfig.BOSS_WORLD_EDGE_MARGIN + halfH + 8
        let maxY = GameConfig.WORLD_HEIGHT - GameConfig.BOSS_WORLD_EDGE_MARGIN - halfH - 8
        if (rt.sprite.x <= minX && targetVX < 0) targetVX = Math.abs(targetVX)
        else if (rt.sprite.x >= maxX && targetVX > 0) targetVX = 0 - Math.abs(targetVX)
        if (rt.sprite.y <= minY && targetVY < 0) targetVY = Math.abs(targetVY)
        else if (rt.sprite.y >= maxY && targetVY > 0) targetVY = 0 - Math.abs(targetVY)
        let nextVX = rt.sprite.vx * (1 - blend) + targetVX * blend
        let nextVY = rt.sprite.vy * (1 - blend) + targetVY * blend
