        let leftSpeed = Math.max(0, rt.sprite.x - minX) * 1000 / lookahead
        let rightSpeed = Math.max(0, maxX - rt.sprite.x) * 1000 / lookahead
        let upSpeed = Math.max(0, rt.sprite.y - minY) * 1000 / lookahead
        let downSpeed = Math.max(0, maxY - rt.sprite.y) * 1000 / lookahead
        if (nextVX < 0 && 0 - nextVX > leftSpeed) nextVX = 0 - leftSpeed
        if (nextVX > 0 && nextVX > rightSpeed) nextVX = rightSpeed
        if (nextVY < 0 && 0 - nextVY > upSpeed) nextVY = 0 - upSpeed
        if (nextVY > 0 && nextVY > downSpeed) nextVY = downSpeed
