            BossWallSpecial.clearOwner(owner)
            rt.rushTelegraphEndsAt = 0; rt.rushChargeEndsAt = 0; rt.rushTargetVX = 0; rt.rushTargetVY = 0; rt.rushNormalRecoveryEnd = 0
