            if (age >= 2750 && !secondActionTriggered) { secondActionTriggered = true; ShieldSystem.prepareTutorialUse(); ShieldSystem.releaseShield() }
            if (age >= 4600 && !thirdActionTriggered) { thirdActionTriggered = true; ShieldSystem.prepareTutorialUse(); ShieldSystem.releaseShield() }
