namespace HudSystem {
    export function startBossBarIntro() {
        bossBarIntroStartAt = game.runtime()
        bossBarIntroEndAt = bossBarIntroStartAt + GameConfig.BOSS_BAR_INTRO_MS
        updateBossHP()
    }
    export function finishBossBarIntro() {
        bossBarIntroStartAt = 0
        bossBarIntroEndAt = 0
        updateBossHP()
    }
    export function updateBossHP() {
        if (bossBar == null) return
        let barImage = bossBarBuffer
        if (barImage == null) {
            barImage = image.create(GameConfig.SCREEN_WIDTH, GameConfig.BOSS_BAR_HEIGHT)
            bossBarBuffer = barImage
            bossBar.setImage(barImage)
        }
        barImage.fill(0)
        if (MinionSystem.isStageActive()) {
            let hp = MinionSystem.getCombinedHP(), maxHP = MinionSystem.getCombinedMaxHP()
            if (maxHP > 0 && hp > 0) {
                let width = Math.idiv(hp * GameConfig.SCREEN_WIDTH, maxHP)
                if (width < 1) width = 1
                barImage.fillRect(0, 0, width, GameConfig.BOSS_BAR_HEIGHT, 7)
            }
            return
        }
        let hp = BossSystem.getHP(), maxHP = BossSystem.getMaxHP()
        if (BossSystem.isAlive() && hp > 0 && maxHP > 0) {
            let redWidth = Math.idiv(hp * GameConfig.SCREEN_WIDTH, maxHP)
            if (redWidth < 1) redWidth = 1
            if (game.runtime() < bossBarIntroEndAt && bossBarIntroEndAt > bossBarIntroStartAt) {
                let now = game.runtime()
                let elapsed = now - bossBarIntroStartAt
                if (elapsed < 0) elapsed = 0
                let duration = bossBarIntroEndAt - bossBarIntroStartAt
                let p = Math.idiv(Math.min(elapsed, duration) * 1000, duration)
                let eased = Math.idiv(p * p * (3000 - 2 * p), 1000000)
                redWidth = Math.idiv(redWidth * eased, 1000)
                if (redWidth < 0) redWidth = 0
                if (redWidth > 0) {
                    barImage.fillRect(0, 0, redWidth, GameConfig.BOSS_BAR_HEIGHT, 2)
                    let tailStart = Math.max(0, redWidth - 10)
                    if (redWidth - tailStart > 0) barImage.fillRect(tailStart, 0, redWidth - tailStart, GameConfig.BOSS_BAR_HEIGHT, 4)
                    let tipStart = Math.max(0, redWidth - 3)
                    if (redWidth - tipStart > 0) barImage.fillRect(tipStart, 0, redWidth - tipStart, GameConfig.BOSS_BAR_HEIGHT, 1)
                }
                if (p < 1000 && Math.idiv(now, 90) % 2 == 0 && redWidth < GameConfig.SCREEN_WIDTH - 1) barImage.setPixel(redWidth, 0, 1)
            } else if (redWidth > 0) {
                barImage.fillRect(0, 0, redWidth, GameConfig.BOSS_BAR_HEIGHT, 2)
            }
        }
    }
    export function updateShieldCooldown() {
        if (shieldCooldownBar == null) return
        let width = GameConfig.SHIELD_COOLDOWN_BAR_WIDTH
        let height = GameConfig.SHIELD_COOLDOWN_BAR_HEIGHT
        let innerHeight = height - 2
        let progress = ShieldSystem.getCooldownProgress1000()
        let fillHeight = Math.idiv(innerHeight * progress, 1000)
        let ready = progress >= 1000
        if (fillHeight != lastShieldFillHeight || ready != lastShieldReadyState) {
            lastShieldFillHeight = fillHeight
            lastShieldReadyState = ready
            let barImage = shieldCooldownBuffer
            if (barImage == null) {
                barImage = image.create(width, height)
                shieldCooldownBuffer = barImage
                shieldCooldownBar.setImage(barImage)
            }
            barImage.fill(0)
            barImage.fillRect(0, 0, width, height, 12)
            if (fillHeight > 0) {
                let fillColor = ready ? 7 : 6
                barImage.fillRect(1, height - 1 - fillHeight, width - 2, fillHeight, fillColor)
            }
        }
        updateShieldReadyEffect()
    }
    export function showShieldReadyAnimation() {
        shieldReadyEffectUntil = game.runtime() + 650
        lastShieldEffectFrame = -1
        if (shieldReadyEffect != null) shieldReadyEffect.setFlag(SpriteFlag.Invisible, false)
    }
    function updateShieldReadyEffect() {
        if (shieldReadyEffect == null) return
        let now = game.runtime()
        if (now >= shieldReadyEffectUntil) {
            shieldReadyEffect.setFlag(SpriteFlag.Invisible, true)
            lastShieldEffectFrame = -1
            return
        }
        let frame = Math.idiv(shieldReadyEffectUntil - now, 100) % 3
        if (frame != lastShieldEffectFrame) {
            lastShieldEffectFrame = frame
            let fx = shieldReadyEffectBuffer
            if (fx == null) {
                fx = image.create(10, 54)
                shieldReadyEffectBuffer = fx
                shieldReadyEffect.setImage(fx)
            }
            fx.fill(0)
            if (frame == 0) {
                fx.fillRect(7, 1, 1, 52, 7)
                fx.fillRect(4, 7, 1, 40, 6)
            } else if (frame == 1) {
                fx.fillRect(6, 0, 2, 54, 1)
                fx.fillRect(3, 5, 1, 44, 7)
            } else {
                fx.fillRect(7, 3, 1, 48, 6)
                fx.fillRect(5, 11, 1, 32, 1)
            }
        }
        shieldReadyEffect.setFlag(SpriteFlag.Invisible, false)
    }
}
namespace HudSystem {
    function setTimeHudRow(y: number) {
        if (timeMinuteTens == null) return
        timeMinuteTens.setPosition(137, y); timeMinuteOnes.setPosition(141, y); timeColon.setPosition(145, y)
        timeSecondTens.setPosition(149, y); timeSecondOnes.setPosition(153, y)
    }
    export function updateRunModeIndicator() {
        if (runModeIndicator == null) return
        let gameplayOnly = GameSession.isRunning() && !GameSession.isTutorialMode() && !openingHowToPlayVisible && !customGameOverVisible && clearBreakdownUntil <= 0 && !BossSystem.isAwaitingStageConfirm()
        let demo = GameSession.isDemoMode()
        let baseLabel = demo ? "DEMO" : GameSession.getRunModeLabel()
        if (!gameplayOnly) { runModeIndicator.setFlag(SpriteFlag.Invisible, true); setTimeHudRow(7); return }
        if (baseLabel == "CLASSIC") {
            runModeIndicator.setFlag(SpriteFlag.Invisible, true)
            setTimeHudRow(7)
            updateTime()
            return
        }
        setTimeHudRow(14)
        let label = baseLabel
        let width = Math.max(1, label.length * 6 - 1)
        let img = image.create(width, 5)
        let color = demo ? 5 : 3
        img.print(label, 0, 0, color, image.font5)
        runModeIndicator.setImage(img)
        let rightEdge = 154
        runModeIndicator.setPosition(rightEdge - Math.idiv(width - 1, 2), 7)
        runModeIndicator.setFlag(SpriteFlag.Invisible, false)
        updateTime()
    }
    export function updateScore() {
        if (scoreDigits.length == 0) {
            return
        }
        if (tutorialHudMode) {
            for (let digit of scoreDigits) digit.setFlag(SpriteFlag.Invisible, true)
            return
        }
        let score = ScoreSystem.getDisplayedScore()
        if (score < 0) {
            score = 0
        }
        let bounceY = 0
        for (let index = 0; index < scoreDigits.length; index++) {
            scoreDigits[index].setFlag(SpriteFlag.Invisible, true)
        }
        let digitCount = 5
        let temp = score
        let actualDigits = 1
        while (temp >= 10 && actualDigits < scoreDigits.length) {
            temp = Math.idiv(temp, 10)
            actualDigits += 1
        }
        if (actualDigits > digitCount) {
            digitCount = actualDigits
        }
        let divisor = 1
        for (let index = 1; index < digitCount; index++) {
            divisor *= 10
        }
        for (let index = 0; index < digitCount; index++) {
            let digitValue = Math.idiv(score, divisor) % 10
            let digitSprite = scoreDigits[index]
            digitSprite.setFlag(SpriteFlag.Invisible, false)
            digitSprite.setPosition(3 + index * 4, 7 + bounceY)
            digitSprite.setImage(GameSession.isRankingEligible() ? GameAssets.stageDigit(digitValue) : scoreGrayDigits[digitValue])
            if (divisor > 1) {
                divisor = Math.idiv(divisor, 10)
            }
        }
    }
    export function updateTime() {
        if (timeMinuteTens == null) {
            return
        }
        if (tutorialHudMode) {
            timeMinuteTens.setFlag(SpriteFlag.Invisible, true)
            timeMinuteOnes.setFlag(SpriteFlag.Invisible, true)
            timeColon.setFlag(SpriteFlag.Invisible, true)
            timeSecondTens.setFlag(SpriteFlag.Invisible, true)
            timeSecondOnes.setFlag(SpriteFlag.Invisible, true)
            return
        }
        let hideForMinions = MinionSystem.isStageActive() || MinionSystem.isTransitionActive()
        timeMinuteTens.setFlag(SpriteFlag.Invisible, hideForMinions)
        timeMinuteOnes.setFlag(SpriteFlag.Invisible, hideForMinions)
        timeColon.setFlag(SpriteFlag.Invisible, hideForMinions)
        timeSecondTens.setFlag(SpriteFlag.Invisible, hideForMinions)
        timeSecondOnes.setFlag(SpriteFlag.Invisible, hideForMinions)
        if (hideForMinions) {
            return
        }
        let remainingMs = BossSystem.getStageCountdownMs()
        let totalSeconds = Math.idiv(remainingMs + 999, 1000)
        if (totalSeconds < 0) {
            totalSeconds = 0
        }
        if (totalSeconds > 5999) {
            totalSeconds = 5999
        }
        let minutes = Math.idiv(totalSeconds, 60)
        let seconds = totalSeconds % 60
        timeMinuteTens.setImage(GameAssets.stageDigit(Math.idiv(minutes, 10)))
        timeMinuteOnes.setImage(GameAssets.stageDigit(minutes % 10))
        timeSecondTens.setImage(GameAssets.stageDigit(Math.idiv(seconds, 10)))
        timeSecondOnes.setImage(GameAssets.stageDigit(seconds % 10))
    }
    export function updateStage() {
        if (stageDigits.length == 0) {
            return
        }
        let level = StageSystem.getLevel()
        if (level < 1) {
            level = 1
        }
        for (let index = 0; index < stageDigits.length; index++) {
            stageDigits[index].setFlag(SpriteFlag.Invisible, true)
        }
        let digitCount = 1
        let divisor = 1
        let temp = level
        while (temp >= 10 && digitCount < stageDigits.length) {
            temp = Math.idiv(temp, 10)
            divisor *= 10
            digitCount += 1
        }
        let practiceTint = !GameSession.isRankingEligible()
        if (stageLabel != null) stageLabel.setImage(practiceTint && stagePracticeLabel != null ? stagePracticeLabel : GameAssets.stageLabel())
        for (let index = 0; index < digitCount; index++) {
            let digitValue = Math.idiv(level, divisor) % 10
            let digitSprite = stageDigits[index]
            digitSprite.setFlag(SpriteFlag.Invisible, false)
            digitSprite.setPosition(22 + index * 4, 116)
            digitSprite.setImage(practiceTint ? scoreGrayDigits[digitValue] : GameAssets.stageDigit(digitValue))
            if (divisor > 1) {
                divisor = Math.idiv(divisor, 10)
            }
        }
    }
}
