    export function drawTutorialLoopTransition(panel: Image) {
        let p = TutorialSystem.getTransitionProgress1000(); if (p >= 1000) return
        let cover = Math.idiv((1000 - p) * 80 + 999, 1000); if (cover < 1) return
        panel.fillRect(0, 31, cover, 50, 15)
        panel.fillRect(160 - cover, 31, cover, 50, 15)
    }
    export function drawTutorialUiTransition(panel: Image) {
        let p = TutorialSystem.getTransitionProgress1000(); if (p >= 1000) return
        let cover = 0
        if (p < 500) cover = Math.idiv(p * 160 + 499, 1000)
        else cover = Math.idiv((1000 - p) * 160 + 499, 1000)
        if (cover < 1) return
        if (cover > 80) cover = 80
        panel.fillRect(0, 0, cover, 120, 15)
        panel.fillRect(160 - cover, 0, cover, 120, 15)
        if (cover < 80) { panel.drawLine(cover - 1, 0, cover - 1, 119, 12); panel.drawLine(160 - cover, 0, 160 - cover, 119, 12) }
    }
