    export function drawFooterAB(panel: Image, aLabel: string, bLabel: string) {
        drawKeyButton(panel, 22, 94, "A", true, 0)
        panel.print(aLabel, 36, 95, 1, image.font5)
        drawKeyButton(panel, 91, 94, "B", false, 150)
        panel.print(bLabel, 105, 95, 1, image.font5)
    }
    function buildLargeText2x(text: string, color: number): Image {
        let source = image.create(text.length * 6, 5)
        source.print(text, 0, 0, color, image.font5)
        let scaled = image.create(source.width * 2, source.height * 2)
        for (let sy = 0; sy < source.height; sy++) {
            for (let sx = 0; sx < source.width; sx++) {
                let pixel = source.getPixel(sx, sy)
                if (pixel != 0) scaled.fillRect(sx * 2, sy * 2, 2, 2, pixel)
            }
        }
        return scaled
    }
    export function drawLargeText2x(panel: Image, text: string, y: number, color: number) {
        let scaled: Image = null
        if (text == "GAME OVER" && color == 2) {
            if (gameOverLargeTextCache == null) gameOverLargeTextCache = buildLargeText2x(text, color)
            scaled = gameOverLargeTextCache
        } else if (text == "BOSS CLEAR" && color == 5) {
            if (bossClearLargeTextCache == null) bossClearLargeTextCache = buildLargeText2x(text, color)
            scaled = bossClearLargeTextCache
        } else scaled = buildLargeText2x(text, color)
        panel.drawTransparentImage(scaled, Math.idiv(GameConfig.SCREEN_WIDTH - scaled.width, 2), y)
    }
