    function formatMultiplierBonusLine(label: string, multiplier: string, bonus: number): string {
        let full = label + " x" + multiplier + " +" + bonus
        if (full.length * 6 <= 146) return full
        return label + " +" + bonus
    }
    function bossMultiplierLabel(count: number): string {
        if (count == 2) return "DOUBLE BOSS"
        if (count == 3) return "TRIPLE BOSS"
        return "" + count + " BOSSES"
    }
    export function drawStageClearScorePage(panel: Image) {
        let elapsed = game.runtime() - clearBreakdownUntil
        drawModalTitle(panel, "STAGE CLEAR")
        let hasReward = clearTimeBonus > 0 || clearDamageBonus > 0 || clearShieldKill || clearBossCountMultiplier > 1 || clearTotalBonus > 0
        let showScore = !GameSession.isRankingEligible() || !hasReward
        let y = 34
        if (showScore) {
            let score = ScoreSystem.getDisplayedScore(); if (score < 0) score = 0
            let scoreText = "" + score; while (scoreText.length < 5) scoreText = "0" + scoreText
            let scoreLine = "SCORE " + scoreText
            panel.print(scoreLine, Math.idiv(160 - scoreLine.length * 6, 2), 30, 5, image.font5)
            y = 42
        }
        if (elapsed >= 300 && clearTimeBonus > 0) {
            let line = "TIME +" + clearTimeBonus; panel.print(line, Math.idiv(160 - line.length * 6, 2), y, 1, image.font5); y += 10
        }
        if (elapsed >= 750 && clearDamageBonus > 0 && clearDamageCount <= 1) {
            let label = clearDamageCount == 0 ? "NO HIT" : "ONE HIT"
            let multiplier = clearDamageCount == 0 ? "2" : "1.5"
            let line = formatMultiplierBonusLine(label, multiplier, clearDamageBonus)
            panel.print(line, Math.idiv(160 - line.length * 6, 2), y, 5, image.font5); y += 10
        }
        if (elapsed >= 1200 && clearShieldKill) {
            let multiplier = ScoreRules.multiplierTextX10(clearShieldMultiplierX10)
            let line = formatMultiplierBonusLine("SHIELD KILL", multiplier, clearShieldMultiplierBonus)
            panel.print(line, Math.idiv(160 - line.length * 6, 2), y, 5, image.font5); y += 10
        }
        if (elapsed >= 1650 && clearBossCountMultiplier > 1) {
            let label = bossMultiplierLabel(clearBossCountMultiplier)
            let line = formatMultiplierBonusLine(label, "" + clearBossCountMultiplier, clearBossCountMultiplierBonus)
            panel.print(line, Math.idiv(160 - line.length * 6, 2), y, 5, image.font5); y += 10
        }
        if (elapsed >= 2100 && clearTotalBonus > 0) {
            let pulseColor = Math.idiv(game.runtime(), 120) % 2 == 0 ? 5 : 1
            let line = "TOTAL +" + clearTotalBonus
            panel.print(line, Math.idiv(160 - line.length * 6, 2), y, pulseColor, image.font5)
        }
        drawFooterAB(panel, "NEXT", "TUTORIAL")
    }
