namespace CombatSystem {
    let bulletCenterWhite = true
    let bulletCenterTouchedImages: Image[] = []
    let homingMissiles: Sprite[] = []
    let homingTargets: Sprite[] = []
    let homingSeekWhenClose: boolean[] = []
    let homingAimAngles: number[] = []
    let homingTrailX: number[] = []
    let homingTrailY: number[] = []
    let homingTrailAt: number[] = []
    let needleBullets: Sprite[] = []
    let needleOriginX: number[] = []
    let needleOriginY: number[] = []
    let missileExplosions: Sprite[] = []
    let missileExplosionBorn: number[] = []
    let missileExplosionHits: Sprite[][] = []
    let missileExplosionFrames: Image[] = []
    function isHomingMissileSprite(bullet: Sprite): boolean {
        for (let m of homingMissiles) if (m == bullet) return true
        return false
    }
    function needleIndex(bullet: Sprite): number {
        for (let i = 0; i < needleBullets.length; i++)if (needleBullets[i] == bullet) return i
        return -1
    }
    function registerNeedleBullet(bullet: Sprite, x: number, y: number) {
        needleBullets.push(bullet); needleOriginX.push(x); needleOriginY.push(y)
    }
    function removeNeedleAt(i: number) {
        if (i < 0 || i >= needleBullets.length) return
        let last = needleBullets.length - 1
        if (i != last) { needleBullets[i] = needleBullets[last]; needleOriginX[i] = needleOriginX[last]; needleOriginY[i] = needleOriginY[last] }
        needleBullets.pop(); needleOriginX.pop(); needleOriginY.pop()
    }
    function forgetNeedleBullet(bullet: Sprite) {
        let i = needleIndex(bullet)
        if (i >= 0) removeNeedleAt(i)
    }
    function needleDamageForHit(bullet: Sprite): number {
        let i = needleIndex(bullet)
        if (i < 0) return 1
        let dx = bullet.x - needleOriginX[i], dy = bullet.y - needleOriginY[i]
        let d = Math.sqrt(dx * dx + dy * dy)
        if (d <= 64) return 1
        let noDamageChance = d <= 128 ? 20 : 40
        return randint(1, 100) <= noDamageChance ? 0 : 1
    }
    function showNeedleMuzzleFlash(x: number, y: number, vx: number, vy: number) {
        let fx = sprites.create(img`
            . 5 .
            5 1 5
            . 5 .
        `, SpriteKind.MinionEffect)
        fx.setFlag(SpriteFlag.Ghost, true)
        fx.z = GameConfig.PLAYER_Z + 2
        fx.setPosition(x, y)
        let mag = Math.sqrt(vx * vx + vy * vy)
        if (mag > 0) { fx.vx = vx / mag * 18; fx.vy = vy / mag * 18 }
        fx.lifespan = 70
        control.runInParallel(function () {
            pause(30)
            if (fx != null) fx.setImage(img`
                5 . 5
                . 4 .
                5 . 5
            `)
        })
    }
    function playerHitEffectFrame(needle: boolean, frame: number): Image {
        if (needle) {
            if (frame <= 0) return img`
                . . . 5 . . .
                . 5 . 1 . 5 .
                . . 4 1 4 . .
                5 1 1 1 1 1 5
                . . 4 1 4 . .
                . 5 . 1 . 5 .
                . . . 5 . . .
            `
            if (frame == 1) return img`
                5 . . . . . 5
                . 5 . 4 . 5 .
                . . 5 1 5 . .
                . 4 1 . 1 4 .
                . . 5 1 5 . .
                . 5 . 4 . 5 .
                5 . . . . . 5
            `
            return img`
                . 5 . . . 5 .
                5 . . 4 . . 5
                . . . . . . .
                . 4 . 1 . 4 .
                . . . . . . .
                5 . . 4 . . 5
                . 5 . . . 5 .
            `
        }
        if (frame <= 0) return img`
            . . 5 . .
            . 5 4 5 .
            5 4 1 4 5
            . 5 4 5 .
            . . 5 . .
        `
        if (frame == 1) return img`
            5 . . . 5
            . 5 4 5 .
            . 4 1 4 .
            . 5 4 5 .
            5 . . . 5
        `
        return img`
            . 5 . 5 .
            5 . . . 5
            . . 1 . .
            5 . . . 5
            . 5 . 5 .
        `
    }
    function showPlayerHitEffect(x: number, y: number, needle: boolean) {
        let fx = sprites.create(playerHitEffectFrame(needle, 0), SpriteKind.MinionEffect)
        fx.setFlag(SpriteFlag.Ghost, true)
        fx.z = GameConfig.PLAYER_BULLET_Z + 1
        fx.setPosition(x, y)
        fx.lifespan = 135
        control.runInParallel(function () {
            pause(42)
            if (fx != null) fx.setImage(playerHitEffectFrame(needle, 1))
            pause(42)
            if (fx != null) fx.setImage(playerHitEffectFrame(needle, 2))
        })
    }
    function buildMissileFireballFrame(frame: number): Image {
        let size = 19, out = image.create(size, size), c = Math.idiv(size, 2)
        let pulse = frame % 4
        let r = 6 + (pulse == 1 ? 1 : (pulse == 3 ? 1 : 0))
        for (let y = 0; y < size; y++)for (let x = 0; x < size; x++) {
            let dx = x - c, dy = y - c, d2 = dx * dx + dy * dy
            if (d2 <= r * r) {
                let color = 4
                if (d2 <= (r - 2) * (r - 2)) color = 5
                if (d2 <= (r - 4) * (r - 4)) color = 1
                if ((x * 3 + y * 5 + frame) % 11 == 0) color = 2
                out.setPixel(x, y, color)
            }
        }
        for (let n = 0; n < 8; n++) {
            let a = (n * 45 + frame * 13) * Math.PI / 180
            let rr = r + 1 + (n % 2)
            let x = Math.round(c + Math.cos(a) * rr), y = Math.round(c + Math.sin(a) * rr)
            if (x >= 0 && x < size && y >= 0 && y < size) out.setPixel(x, y, n % 2 == 0 ? 4 : 5)
        }
        return out
    }
    function ensureMissileFireballFrames() {
        if (missileExplosionFrames.length > 0) return
        for (let i = 0; i < 4; i++)missileExplosionFrames.push(buildMissileFireballFrame(i))
    }
    function createMissileExplosion(x: number, y: number) {
        ensureMissileFireballFrames()
        let fx = sprites.create(missileExplosionFrames[0], SpriteKind.MissileExplosion)
        fx.setFlag(SpriteFlag.Ghost, false)
        fx.setFlag(SpriteFlag.AutoDestroy, false)
        fx.z = GameConfig.PLAYER_BULLET_Z + 2
        fx.setPosition(x, y)
        missileExplosions.push(fx); missileExplosionBorn.push(game.runtime()); missileExplosionHits.push([])
        SoundSystem.playerMissileImpact()
        scene.cameraShake(1, 80)
    }
    function missileExplosionIndex(fx: Sprite): number {
        for (let i = 0; i < missileExplosions.length; i++)if (missileExplosions[i] == fx) return i
        return -1
    }
    function missileExplosionAlreadyHit(index: number, target: Sprite): boolean {
        if (index < 0 || index >= missileExplosionHits.length) return true
        for (let t of missileExplosionHits[index]) if (t == target) return true
        return false
    }
    function markMissileExplosionHit(index: number, target: Sprite) {
        if (index < 0 || index >= missileExplosionHits.length) return
        missileExplosionHits[index].push(target)
    }
    function destroyMissileExplosion(fx: Sprite) {
        let index = missileExplosionIndex(fx)
        if (index < 0) {
            if (fx != null) fx.destroy()
            return
        }
        missileExplosions.removeAt(index)
        missileExplosionBorn.removeAt(index)
        missileExplosionHits.removeAt(index)
        if (fx != null) fx.destroy()
    }
    function updateMissileExplosions() {
        if (missileExplosions.length <= 0) return
        ensureMissileFireballFrames()
        let now = game.runtime()
        for (let i = missileExplosions.length - 1; i >= 0; i--) {
            let fx = missileExplosions[i]
            let age = now - missileExplosionBorn[i]
            if (fx == null || age >= 1500) {
                if (fx != null) fx.destroy()
                missileExplosions.removeAt(i); missileExplosionBorn.removeAt(i); missileExplosionHits.removeAt(i)
                continue
            }
            fx.setImage(missileExplosionFrames[Math.idiv(age, 90) % 4])
        }
    }
    function enemyBulletCoreHit(core: Sprite, bullet: Sprite): boolean {
        if (core == null || bullet == null || bullet.image == null) return false
        let source = bullet.image
        if (BulletPatternSystem.isMegaBullet(bullet)) {
            let localX = Math.floor(core.x - bullet.left)
            let localY = Math.floor(core.y - bullet.top)
            if (localX < 0 || localY < 0 || localX >= source.width || localY >= source.height) return false
            return source.getPixel(localX, localY) != 0
        }
        let minX = source.width, minY = source.height, maxX = -1, maxY = -1
        for (let y = 0; y < source.height; y++)for (let x = 0; x < source.width; x++) {
            if (source.getPixel(x, y) == 0) continue
            if (x < minX) minX = x; if (x > maxX) maxX = x
            if (y < minY) minY = y; if (y > maxY) maxY = y
        }
        if (maxX < minX || maxY < minY) return false
        let spanX = maxX - minX + 1, spanY = maxY - minY + 1
        let size = Math.max(spanX, spanY)
        let radius = 0.55
        if (size > 3 && size <= 5) radius = 1.35
        else if (size > 5 && size <= 7) radius = 2.0
        else if (size > 7 && size <= 9) radius = 2.8
        else if (size > 9) radius = Math.max(3, size * 0.30)
        if (size > 5 && GameAssets.isBossWallDart(source)) radius = 1.35
        let dx = core.x - bullet.x, dy = core.y - bullet.y
        return dx * dx + dy * dy <= radius * radius
    }
    export function init() {
        bulletCenterWhite = true
        needleBullets = []; needleOriginX = []; needleOriginY = []
        missileExplosions = []; missileExplosionBorn = []; missileExplosionHits = []; missileExplosionFrames = []
        sprites.onOverlap(
            SpriteKind.PlayerBullet,
            SpriteKind.Enemy,
            function (bullet, enemy) {
                if (!GameSession.isRunning()) {
                    return
                }
                let missile = isHomingMissileSprite(bullet)
                if (missile) {
                    createMissileExplosion(bullet.x, bullet.y)
                    bullet.destroy()
                    return
                }
                let needle = needleIndex(bullet) >= 0
                SoundSystem.playerProjectileImpact(needle)
                showPlayerHitEffect(bullet.x, bullet.y, needle)
                let damage = needleDamageForHit(bullet)
                if (damage > 0) SoundSystem.projectileTargetHurt(BossSystem.getEnemyTypeForSprite(enemy), true)
                bullet.destroy()
                if (BossSystem.isBossEnemy(enemy)) {
                    BossSystem.damageEnemy(enemy, damage)
                } else {
                    enemy.destroy(effects.disintegrate, 200)
                }
            }
        )
        sprites.onOverlap(
            SpriteKind.PlayerBullet,
            SpriteKind.Minion,
            function (bullet, enemy) {
                if (!GameSession.isRunning()) return
                let missile = isHomingMissileSprite(bullet)
                if (missile) {
                    createMissileExplosion(bullet.x, bullet.y)
                    bullet.destroy()
                    return
                }
                let needle = needleIndex(bullet) >= 0
                SoundSystem.playerProjectileImpact(needle)
                showPlayerHitEffect(bullet.x, bullet.y, needle)
                let damage = needleDamageForHit(bullet)
                if (damage > 0) SoundSystem.projectileTargetHurt(MinionSystem.getEnemyType(enemy), false)
                bullet.destroy()
                MinionSystem.damageEnemy(enemy, damage)
            }
        )
        sprites.onOverlap(
            SpriteKind.PlayerBullet,
            SpriteKind.HybridCore,
            function (bullet, core) {
                if (!GameSession.isRunning()) return
                if (isHomingMissileSprite(bullet)) {
                    createMissileExplosion(bullet.x, bullet.y)
                    bullet.destroy()
                    return
                }
                let needle = needleIndex(bullet) >= 0
                SoundSystem.playerProjectileImpact(needle)
                showPlayerHitEffect(bullet.x, bullet.y, needle)
                let damage = needleDamageForHit(bullet)
                if (damage > 0) BossHybridSpecial.damage(core, damage, true)
                bullet.destroy()
            }
        )
        sprites.onOverlap(
            SpriteKind.MissileExplosion,
            SpriteKind.HybridCore,
            function (explosion, core) {
                if (!GameSession.isRunning()) return
                let index = missileExplosionIndex(explosion)
                if (index < 0 || missileExplosionAlreadyHit(index, core)) return
                markMissileExplosionHit(index, core)
                BossHybridSpecial.damage(core, 4, false)
                destroyMissileExplosion(explosion)
            }
        )
        sprites.onOverlap(
            SpriteKind.PlayerCore,
            SpriteKind.Minion,
            function (core, enemy) {
                if (!GameSession.isRunning()) return
                if (ShieldSystem.isProtectingPlayer()) return
                PlayerSystem.damage()
                MinionSystem.knockBack(enemy)
            }
        )
        sprites.onOverlap(
            SpriteKind.PlayerCore,
            SpriteKind.BossBullet,
            function (core, bullet) {
                if (!GameSession.isRunning() || BossSystem.isAwaitingStageConfirm()) {
                    return
                }
                if (!enemyBulletCoreHit(core, bullet)) return
                GrazeSystem.markHit(bullet)
                if (!BulletPatternSystem.isMegaBullet(bullet)) bullet.destroy()
                if (ShieldSystem.isProtectingPlayer()) {
                    return
                }
                PlayerSystem.damage()
            }
        )
        sprites.onOverlap(
            SpriteKind.PlayerCore,
            SpriteKind.HybridCore,
            function (playerCore, hybridCore) {
                if (!GameSession.isRunning()) return
                if (ShieldSystem.isProtectingPlayer()) return
                PlayerSystem.damage()
            }
        )
        sprites.onOverlap(
            SpriteKind.PlayerCore,
            SpriteKind.Enemy,
            function (core, enemy) {
                if (!GameSession.isRunning()) {
                    return
                }
                if (ShieldSystem.isProtectingPlayer()) {
                    return
                }
                PlayerSystem.damage()
            }
        )
        sprites.onOverlap(SpriteKind.MissileExplosion, SpriteKind.Enemy, function (explosion, enemy) {
            if (!GameSession.isRunning()) return
            let i = missileExplosionIndex(explosion)
            if (i < 0 || missileExplosionAlreadyHit(i, enemy)) return
            markMissileExplosionHit(i, enemy)
            SoundSystem.projectileTargetHurt(BossSystem.getEnemyTypeForSprite(enemy), true)
            BossSystem.damageEnemy(enemy, 4)
        })
        sprites.onOverlap(SpriteKind.MissileExplosion, SpriteKind.Minion, function (explosion, enemy) {
            if (!GameSession.isRunning()) return
            let i = missileExplosionIndex(explosion)
            if (i < 0 || missileExplosionAlreadyHit(i, enemy)) return
            markMissileExplosionHit(i, enemy)
            SoundSystem.projectileTargetHurt(MinionSystem.getEnemyType(enemy), false)
            MinionSystem.damageEnemy(enemy, 4)
        })
        GameUpdateScheduler.every(GameConfig.REFRESH_COMBAT_MS, function () { updateMissileExplosions() })
        GameUpdateScheduler.every(GameConfig.BULLET_FLASH_INTERVAL_MS, function () {
            updateBulletCenters()
        })
        GameUpdateScheduler.every(GameConfig.PLAYER_HOMING_MISSILE_STEER_INTERVAL_MS, function () {
            updateHomingMissiles()
        })
        sprites.onDestroyed(SpriteKind.PlayerBullet, function (bullet) {
            forgetHomingMissile(bullet)
            forgetNeedleBullet(bullet)
        })
    }
    export function fireNormalAtTarget(target: Sprite) {
        if (!GameSession.isRunning() || PlayerSystem.isRespawning() || target == null) return
        let player = PlayerSystem.getPlayer()
        if (player == null) return
        fireStraightDirection(player, target.x - player.x, target.y - player.y, GameConfig.PLAYER_BULLET_SPEED, false)
    }
    export function fireMissileCycle(target: Sprite, directionX: number, directionY: number) {
        if (!GameSession.isRunning() || PlayerSystem.isRespawning()) return
        let player = PlayerSystem.getPlayer()
        if (player == null) return
        if (target != null) {
            fireAtTarget(player, target)
            return
        }
        if (directionX == 0 && directionY == 0) { directionX = 0; directionY = -1 }
        let mag = Math.sqrt(directionX * directionX + directionY * directionY)
        if (mag <= 0) return
        let speed = GameConfig.PLAYER_BULLET_SPEED * GameConfig.PLAYER_HOMING_MISSILE_SPEED_MULTIPLIER
        createPlayerBullet(player, directionX / mag * speed, directionY / mag * speed, false, true, null, true)
    }
    export function fireNeedleRewardMissile(directionX: number, directionY: number) {
        if (!GameSession.isRunning() || PlayerSystem.isRespawning()) return
        if (directionX == 0 && directionY == 0) return
        let player = PlayerSystem.getPlayer(); if (player == null) return
        let mag = Math.sqrt(directionX * directionX + directionY * directionY); if (mag <= 0) return
        let nx = directionX / mag, ny = directionY / mag
        let speed = GameConfig.PLAYER_BULLET_SPEED * GameConfig.PLAYER_HOMING_MISSILE_SPEED_MULTIPLIER
        let target = TargetSystem.getTarget()
        createPlayerBullet(player, nx * speed, ny * speed, false, true, target, target == null)
    }
    export function firePlayerBullet() {
        if (!GameSession.isRunning() || PlayerSystem.isRespawning()) {
            return
        }
        let player = PlayerSystem.getPlayer()
        let directionX = PlayerSystem.getCurrentDirectionX()
        let directionY = PlayerSystem.getCurrentDirectionY()
        if (PlayerSystem.isFastAttackActive()) {
            if (directionX == 0 && directionY == 0) {
                directionX = PlayerSystem.getLastDirectionX()
                directionY = PlayerSystem.getLastDirectionY()
            }
            if (directionX != 0 || directionY != 0) {
                fireStraightDirection(
                    player,
                    PlayerSystem.getVisualAimX(),
                    PlayerSystem.getVisualAimY(),
                    GameConfig.PLAYER_BULLET_SPEED * GameConfig.PLAYER_B_HELD_BULLET_SPEED_MULTIPLIER,
                    true
                )
            }
            return
        }
        if (directionX != 0 || directionY != 0) {
            fireStraightDirection(
                player,
                PlayerSystem.getVisualAimX(),
                PlayerSystem.getVisualAimY(),
                GameConfig.PLAYER_BULLET_SPEED,
                false
            )
            return
        }
        let target = TargetSystem.getTarget()
        if (target != null) {
            fireAtTarget(player, target)
            return
        }
        directionX = PlayerSystem.getLastDirectionX()
        directionY = PlayerSystem.getLastDirectionY()
        if (directionX != 0 || directionY != 0) {
            fireStraightDirection(
                player,
                directionX,
                directionY,
                GameConfig.PLAYER_BULLET_SPEED,
                false
            )
        }
    }
    function fireAtTarget(player: Sprite, target: Sprite) {
        let dx = target.x - player.x, dy = target.y - player.y
        if (dx == 0 && dy == 0) return
        let angle = Math.atan2(dy, dx)
        angle += randint(-GameConfig.PLAYER_HOMING_MISSILE_INITIAL_SPREAD_DEG, GameConfig.PLAYER_HOMING_MISSILE_INITIAL_SPREAD_DEG) * Math.PI / 180
        let speed = GameConfig.PLAYER_BULLET_SPEED * GameConfig.PLAYER_HOMING_MISSILE_SPEED_MULTIPLIER
        createPlayerBullet(player, Math.cos(angle) * speed, Math.sin(angle) * speed, false, true, target)
    }
    function fireStraightDirection(player: Sprite, directionX: number, directionY: number, bulletSpeed: number, fastMode: boolean) {
        if (directionX == 0 && directionY == 0) return
        let angle = Math.atan2(directionY, directionX)
        let spreadDeg = fastMode ? GameConfig.PLAYER_NEEDLE_SHOT_SPREAD_DEG : GameConfig.PLAYER_STRAIGHT_SHOT_SPREAD_DEG
        angle += randint(-spreadDeg * 10, spreadDeg * 10) * Math.PI / 1800
        createPlayerBullet(player, Math.cos(angle) * bulletSpeed, Math.sin(angle) * bulletSpeed, fastMode, false, null)
    }
    function createPlayerBullet(player: Sprite, vx: number, vy: number, fastMode: boolean, missileMode: boolean, target: Sprite, seekWhenClose?: boolean) {
        let bulletImage = GameAssets.playerBulletNormal()
        if (fastMode) bulletImage = GameAssets.playerNeedle(vx, vy)
        else if (missileMode) bulletImage = GameAssets.playerMissile(vx, vy)
        let bullet = sprites.createProjectileFromSprite(bulletImage, player, vx, vy)
        bullet.setKind(SpriteKind.PlayerBullet)
        bullet.z = GameConfig.PLAYER_BULLET_Z
        bullet.setFlag(SpriteFlag.AutoDestroy, false)
        bullet.lifespan = GameConfig.PLAYER_PROJECTILE_MAX_LIFETIME_MS
        if (!missileMode) {
            let mag = Math.sqrt(vx * vx + vy * vy)
            if (mag > 0) {
                let nx = vx / mag, ny = vy / mag
                let playerRadius = Math.idiv(Math.max(player.width, player.height), 2)
                let muzzle = playerRadius + 4
                bullet.setPosition(player.x + nx * muzzle, player.y + ny * muzzle)
            }
        }
        if (fastMode) {
            registerNeedleBullet(bullet, player.x, player.y)
            showNeedleMuzzleFlash(bullet.x, bullet.y, vx, vy)
        }
        if (missileMode) { registerHomingMissile(bullet, target, seekWhenClose == true); PlayerSystem.applyMissileRecoil(vx, vy); SoundSystem.playerMissileLaunch() }
        else SoundSystem.playerShot(fastMode)
    }
    function registerHomingMissile(missile: Sprite, target: Sprite, seekWhenClose: boolean) {
        homingMissiles.push(missile); homingTargets.push(target); homingSeekWhenClose.push(seekWhenClose)
        homingAimAngles.push(Math.atan2(missile.vy, missile.vx))
        homingTrailX.push(missile.x); homingTrailY.push(missile.y); homingTrailAt.push(game.runtime())
    }
    function removeHomingMissileAt(i: number) {
        if (i < 0 || i >= homingMissiles.length) return
        let last = homingMissiles.length - 1
        if (i != last) {
            homingMissiles[i] = homingMissiles[last]; homingTargets[i] = homingTargets[last]; homingSeekWhenClose[i] = homingSeekWhenClose[last]; homingAimAngles[i] = homingAimAngles[last]
            homingTrailX[i] = homingTrailX[last]; homingTrailY[i] = homingTrailY[last]; homingTrailAt[i] = homingTrailAt[last]
        }
        homingMissiles.pop(); homingTargets.pop(); homingSeekWhenClose.pop(); homingAimAngles.pop(); homingTrailX.pop(); homingTrailY.pop(); homingTrailAt.pop()
    }
    function forgetHomingMissile(missile: Sprite) {
        for (let i = homingMissiles.length - 1; i >= 0; i--)if (homingMissiles[i] == missile) { removeHomingMissileAt(i); return }
    }
    function updateMissileTrail(i: number, missile: Sprite, now: number) {
        if (i < 0 || i >= homingTrailAt.length || missile == null) return
        if (now - homingTrailAt[i] < GameConfig.PLAYER_MISSILE_TRAIL_SAMPLE_MS) return
        let x0 = homingTrailX[i], y0 = homingTrailY[i], x1 = missile.x, y1 = missile.y
        homingTrailX[i] = x1; homingTrailY[i] = y1; homingTrailAt[i] = now
        let dx = x1 - x0, dy = y1 - y0; if (dx * dx + dy * dy < 0.04) return
        TrailRibbonSystem.spawnSimpleSegment(missile, SpriteKind.MinionEffect, x0, y0, x1, y1, 0.40, 0.40, 5, GameConfig.PLAYER_MISSILE_TRAIL_DURATION_MS, GameConfig.PLAYER_BULLET_Z - 1, false)
    }
    function nearestMissileTarget(missile: Sprite, maxRadius: number): Sprite {
        let best: Sprite = null
        let bestD = maxRadius * maxRadius
        for (let i = 0; i < EnemyRegistrySystem.count(); i++) {
            let t = EnemyRegistrySystem.actorAt(i); if (t == null) continue
            let dx = t.x - missile.x, dy = t.y - missile.y
            let d = dx * dx + dy * dy
            if (d <= bestD) { bestD = d; best = t }
        }
        return best
    }
    function updateHomingMissiles() {
        if (homingMissiles.length <= 0) return
        let now = game.runtime()
        let baseTurn = GameConfig.PLAYER_HOMING_MISSILE_MAX_TURN_DEG * Math.PI / 180
        let speed = GameConfig.PLAYER_BULLET_SPEED * GameConfig.PLAYER_HOMING_MISSILE_SPEED_MULTIPLIER
        for (let i = homingMissiles.length - 1; i >= 0; i--) {
            let missile = homingMissiles[i]
            if (missile == null) { removeHomingMissileAt(i); continue }
            updateMissileTrail(i, missile, now)
            let target = homingTargets[i]
            let seekClose = homingSeekWhenClose[i]
            if (target == null && seekClose) {
                target = nearestMissileTarget(missile, GameConfig.AUTO_LOCK_RADIUS)
                if (target != null) { homingTargets[i] = target; homingSeekWhenClose[i] = false }
            } else if (!EnemyRegistrySystem.isMissileTarget(target)) {
                let radius = seekClose ? GameConfig.AUTO_LOCK_RADIUS : 180
                target = nearestMissileTarget(missile, radius); homingTargets[i] = target
                if (target != null) homingSeekWhenClose[i] = false
            }
            if (target == null) continue
            let dx = target.x - missile.x, dy = target.y - missile.y
            let dist = Math.sqrt(dx * dx + dy * dy)
            let leadMs = dist > 70 ? 180 : (dist > 36 ? 110 : 45)
            let aimX = target.x + target.vx * leadMs / 1000
            let aimY = target.y + target.vy * leadMs / 1000
            let rawDesired = Math.atan2(aimY - missile.y, aimX - missile.x)
            let filteredDesired = homingAimAngles[i]
            if (filteredDesired == null) filteredDesired = Math.atan2(missile.vy, missile.vx)
            let aimDiff = rawDesired - filteredDesired
            while (aimDiff > Math.PI) aimDiff -= Math.PI * 2
            while (aimDiff < 0 - Math.PI) aimDiff += Math.PI * 2
            let aimStep = baseTurn * 1.8
            if (aimDiff > aimStep) aimDiff = aimStep
            if (aimDiff < 0 - aimStep) aimDiff = 0 - aimStep
            filteredDesired += aimDiff
            homingAimAngles[i] = filteredDesired
            let current = Math.atan2(missile.vy, missile.vx)
            let diff = filteredDesired - current
            while (diff > Math.PI) diff -= Math.PI * 2
            while (diff < 0 - Math.PI) diff += Math.PI * 2
            let maxTurn = baseTurn
            if (dist < 42) maxTurn = baseTurn * 1.35
            else if (dist < 72) maxTurn = baseTurn * 1.15
            if (diff > maxTurn) diff = maxTurn
            if (diff < 0 - maxTurn) diff = 0 - maxTurn
            let next = current + diff
            missile.vx = Math.cos(next) * speed; missile.vy = Math.sin(next) * speed
            missile.setImage(GameAssets.playerMissile(missile.vx, missile.vy))
        }
    }
    function updateBulletCenters() {
        bulletCenterWhite = !bulletCenterWhite
        let color = 15
        if (bulletCenterWhite) {
            color = 1
        }
        let bossBullets = sprites.allOfKind(SpriteKind.BossBullet)
        let touchedCount = 0
        for (let bullet of bossBullets) {
            if (bullet == null || !WorldSystem.isSpriteOnCamera(bullet, 0)) continue
            if (BulletPatternSystem.isMegaBullet(bullet)) continue
            let img = bullet.image
            if (img == null || img.width > 3 || img.height > 3) continue
            let alreadyTouched = false
            for (let j = 0; j < touchedCount; j++)if (bulletCenterTouchedImages[j] == img) { alreadyTouched = true; break }
            if (alreadyTouched) continue
            if (touchedCount < bulletCenterTouchedImages.length) bulletCenterTouchedImages[touchedCount] = img
            else bulletCenterTouchedImages.push(img)
            touchedCount += 1
            img.setPixel(Math.idiv(img.width, 2), Math.idiv(img.height, 2), color)
        }
        while (bulletCenterTouchedImages.length > touchedCount) bulletCenterTouchedImages.pop()
    }
}
